-- Source: database/functions/people/access_policy.sql
CREATE OR REPLACE FUNCTION public.can_manage_member_access_as_actor_internal_v1(p_actor uuid,p_scope text,p_id bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT coalesce(CASE WHEN p_scope='unit' THEN
  NOT public.is_demo_unit(p_id) AND EXISTS(SELECT 1 FROM public.unit_users WHERE unit=p_id AND "user"=p_actor AND is_manager)
 WHEN p_scope='occasion' THEN (SELECT public.participant_manage_rule(
  public.active_membership(m.is_manager,public.is_demo_occasion(o.id)),
  public.active_membership(a.is_admin,public.is_demo_occasion(o.id)))
  FROM public.occasions o LEFT JOIN public.occasion_users m ON m.occasion=o.id AND m."user"=p_actor
  LEFT JOIN public.organization_users a ON a.organization=o.organization AND a."user"=p_actor WHERE o.id=p_id)
 ELSE false END,false) AND p_actor IS NOT NULL;
$$;
REVOKE ALL ON FUNCTION public.can_manage_member_access_as_actor_internal_v1(uuid,text,bigint) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.can_manage_member_access(p_scope text,p_id bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.can_manage_member_access_as_actor_internal_v1(auth.uid(),p_scope,p_id);
$$;
REVOKE ALL ON FUNCTION public.can_manage_member_access(text,bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.can_manage_member_access(text,bigint) TO authenticated;

CREATE OR REPLACE FUNCTION public.lock_member_access_internal_v1(p_unit bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE org bigint;
BEGIN
 -- One ordering shared by account creation, member mutation and token acceptance.
 PERFORM pg_advisory_xact_lock(-p_unit);
 SELECT organization INTO STRICT org FROM public.units WHERE id=p_unit FOR SHARE;
 PERFORM pg_advisory_xact_lock(hashtextextended('user-sign-in-email:'||org::text,0));
END $$;
REVOKE ALL ON FUNCTION public.lock_member_access_internal_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.validate_access_roles_internal_v1(p_scope text,p_roles jsonb)
RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path=public,extensions AS $$
BEGIN
 IF jsonb_typeof(p_roles) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_each(p_roles) r
  WHERE jsonb_typeof(r.value)<>'boolean' OR NOT r.key=ANY(CASE WHEN p_scope='unit'
   THEN ARRAY['is_manager','is_editor','is_editor_view']
   ELSE ARRAY['is_manager','is_editor','is_editor_view','is_editor_order','is_editor_order_view','is_receptionist','is_approver','is_cleaning_crew'] END)) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid_role_scope'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.validate_access_roles_internal_v1(text,jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.stage_member_access_email(p_actor uuid,p_command_id uuid,p_intent_hash text,p_preview_hash text,p_prepared jsonb,p_token_hash text DEFAULT NULL,p_password text DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE preparation uuid;
BEGIN
 PERFORM public.require_service_role();
 IF p_actor IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_actor)
  OR jsonb_typeof(p_prepared) IS DISTINCT FROM 'object' OR jsonb_typeof(p_prepared->'p_sealed') IS DISTINCT FROM 'object'
  OR coalesce(p_prepared->>'p_content_hash','') !~ '^[0-9a-f]{64}$' OR octet_length(p_prepared::text)>1048576
  OR p_token_hash IS NOT NULL AND p_token_hash !~ '^[0-9a-f]{64}$' THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid_preparation'; END IF;
 IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=p_actor AND request_sha256=p_intent_hash AND status='completed') THEN RETURN NULL; END IF;
 DELETE FROM public.access_email_preparations WHERE id IN (SELECT id FROM public.access_email_preparations WHERE expires_at<=now() LIMIT 100);
 DELETE FROM public.access_email_preparations WHERE actor=p_actor AND command_id=p_command_id AND expires_at<=now();
 INSERT INTO public.access_email_preparations(actor,command_id,intent_hash,preview_hash,prepared,token_hash,credential)
 VALUES(p_actor,p_command_id,p_intent_hash,p_preview_hash,p_prepared,p_token_hash,CASE WHEN p_password IS NULL THEN NULL ELSE extensions.pgp_sym_encrypt(p_password,(SELECT encode(secret,'hex') FROM public.access_preparation_key WHERE singleton)) END)
 ON CONFLICT(actor,command_id) DO NOTHING RETURNING id INTO preparation;
 IF preparation IS NULL THEN
  SELECT id INTO preparation FROM public.access_email_preparations
  WHERE actor=p_actor AND command_id=p_command_id AND intent_hash=p_intent_hash AND preview_hash=p_preview_hash;
  IF preparation IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='command_payload_conflict'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=p_actor AND request_sha256=p_intent_hash AND status='completed') THEN
  DELETE FROM public.access_email_preparations WHERE id=preparation; RETURN NULL;
 END IF;
 RETURN preparation;
END $$;
REVOKE ALL ON FUNCTION public.stage_member_access_email(uuid,uuid,text,text,jsonb,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.stage_member_access_email(uuid,uuid,text,text,jsonb,text,text) TO service_role;

-- Setup historically lets a unit manager offer editor/read-only event roles.
-- This does not grant participant management or arbitrary occasion roles.
CREATE OR REPLACE FUNCTION public.can_offer_member_access_as_actor_internal_v1(p_actor uuid,p_scope text,p_id bigint,p_roles jsonb)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.can_manage_member_access_as_actor_internal_v1(p_actor,p_scope,p_id) OR
  (p_scope='occasion' AND NOT public.is_demo_occasion(p_id)
   AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(p_roles) k WHERE k NOT IN ('is_editor','is_editor_view'))
   AND EXISTS(SELECT 1 FROM public.occasions o JOIN public.unit_users m ON m.unit=o.unit
    WHERE o.id=p_id AND m."user"=p_actor AND m.is_manager AND NOT public.is_demo_unit(o.unit)));
$$;
REVOKE ALL ON FUNCTION public.can_offer_member_access_as_actor_internal_v1(uuid,text,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/people/scope.sql
-- Lock the stored resource scope and live authorization facts before delegating.
-- Row locks also fence revocation while a bounded read is in flight.
CREATE OR REPLACE FUNCTION public.lock_people_scope_internal_v1(p_occasion bigint,p_organization bigint DEFAULT NULL,p_unit bigint DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE resource public.occasions%ROWTYPE; organizer public.units%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE insufficient_privilege USING MESSAGE='authenticated identity required'; END IF;
 IF p_occasion IS NOT NULL THEN
  SELECT * INTO resource FROM public.occasions WHERE id=p_occasion FOR SHARE;
  IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='occasion unavailable'; END IF;
  IF (p_organization IS NOT NULL AND resource.organization IS DISTINCT FROM p_organization)
    OR (p_unit IS NOT NULL AND resource.unit IS DISTINCT FROM p_unit) THEN
   RAISE insufficient_privilege USING MESSAGE='occasion scope changed'; END IF;
  SELECT * INTO organizer FROM public.units WHERE id=resource.unit FOR SHARE;
 ELSE
  SELECT * INTO organizer FROM public.units WHERE id=p_unit FOR SHARE;
 END IF;
 IF organizer.id IS NULL OR (p_organization IS NOT NULL AND organizer.organization IS DISTINCT FROM p_organization) THEN
  RAISE insufficient_privilege USING MESSAGE='organizer scope changed'; END IF;
 PERFORM public.lock_member_access_internal_v1(organizer.id);
 PERFORM 1 FROM public.organization_users WHERE organization=organizer.organization AND "user"=auth.uid() FOR SHARE;
 PERFORM 1 FROM public.unit_users WHERE unit=organizer.id AND "user"=auth.uid() FOR SHARE;
 IF p_occasion IS NOT NULL THEN
  PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=auth.uid() FOR SHARE;
 END IF;
END $$;
REVOKE ALL ON FUNCTION public.lock_people_scope_internal_v1(bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/units/begin_unit_client_mutation_v1.sql
CREATE OR REPLACE FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  IF p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid()
     OR p_command_id IS NULL OR p_unit IS NULL
     OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT (CASE WHEN p_command_name IN ('occasion.create','occasion.setup.finalize')
       THEN public.can_create_occasion(p_unit)
       WHEN p_command_name='occasion.delete' THEN public.can_delete_occasion_in_unit(p_unit)
       WHEN p_command_name IN ('unit.information.save','unit.information.delete')
         THEN public.can_write_unit_information(p_unit)
       WHEN p_command_name IN ('unit.icon.save','unit.icon.delete')
         THEN public.can_write_unit_icons(p_unit)
       WHEN p_command_name IN ('unit.email_template.save','unit.email_template.reset','unit.email_banner.save')
         THEN public.can_write_unit_email_templates(p_unit)
       WHEN p_command_name IN ('profile.unit_access.delete','profile.unit_user.save','profile.unit_membership.add') THEN public.can_manage_unit_users(p_unit)
       WHEN p_command_name='unit.config.save' THEN public.can_manage_unit_configuration(p_unit)
       WHEN p_command_name IN ('unit.cards.pause','unit.cards.disconnect') THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name='unit.order_history.delete' THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name='unit.delete' THEN public.can_manage_unit_configuration(p_unit) AND NOT public.is_demo_unit(p_unit)
       WHEN p_command_name IN ('unit.legal.save','unit.legal.submit') THEN public.can_manage_unit_legal_profile(p_unit)
       WHEN p_command_name IN ('unit.bank.save','unit.bank.link','unit.bank.user') THEN public.can_manage_unit_bank_accounts(p_unit)
       WHEN p_command_name='occasion.duplicate' THEN public.can_copy_occasion_target(p_unit)
       ELSE false END) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid unit mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,unit,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_unit,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS NOT NULL OR v_receipt.unit IS DISTINCT FROM p_unit
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id OR v_receipt.actor_client_id IS NOT NULL
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  ELSIF v_receipt.status='expired' THEN
    RETURN jsonb_build_object('disposition','replay',
      'response',public.expired_client_mutation_response_v1(v_receipt));
  END IF;
  IF v_inserted<>1 THEN RAISE serialization_failure
    USING MESSAGE='incomplete mutation receipt cannot be resumed'; END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $function$
;
REVOKE ALL ON FUNCTION public.begin_unit_client_mutation_v1(p_command_id uuid, p_command_name text, p_unit bigint, p_actor_id uuid, p_request_sha256 text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.begin_unit_client_mutation_v1(uuid,text,bigint,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.begin_unit_client_mutation_v1(uuid,text,bigint,uuid,text) TO service_role;


-- Source: database/functions/people/unit_membership.sql
-- Shared membership primitive. Profile and role persistence remain specialized.
CREATE OR REPLACE FUNCTION public.ensure_unit_membership_internal_v1(p_unit bigint,p_user uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE inserted integer;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,NULL,p_unit);
 IF NOT public.can_manage_unit_users(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(-p_unit);
 IF NOT public.can_manage_unit_users(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_info ui JOIN public.units u ON u.organization=ui.organization
   WHERE ui.id=p_user AND u.id=p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='member identity unavailable in unit'; END IF;
 INSERT INTO public.unit_users(unit,"user",is_editor,is_editor_view,is_manager)
 VALUES(p_unit,p_user,false,false,false) ON CONFLICT(unit,"user") DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 RETURN inserted=1;
END $$;
REVOKE ALL ON FUNCTION public.ensure_unit_membership_internal_v1(bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.add_user_to_unit_client_sync_v1(p_unit bigint,p_user uuid,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE initial jsonb; c public.client_commits%ROWTYPE; ver bigint;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,NULL,p_unit);
 IF NOT public.can_manage_unit_users(p_unit) THEN
  RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(-p_unit);
 initial:=public.begin_unit_client_mutation_v1(p_command_id,'profile.unit_membership.add',p_unit,auth.uid(),
  encode(extensions.digest(jsonb_build_object('unit',p_unit,'user',p_user)::text,'sha256'),'hex'));
 IF initial->>'disposition'='replay' THEN RETURN initial->'response'; END IF;
 IF NOT public.ensure_unit_membership_internal_v1(p_unit,p_user) THEN
  SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
   ON v.aggregate_type='unit_user' AND v.scope_type='unit' AND v.scope_id=p_unit AND v.aggregate_id=p_user::text;
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
   jsonb_build_object('userId',p_user,'version',ver,'reasonCode','already_member'));
 END IF;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES('unit_user','unit',p_unit,p_user::text,1)
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp() RETURNING version INTO ver;
 INSERT INTO public.client_commits(unit,actor_id,actor_display,actor_kind,source,change_class)
 SELECT p_unit,auth.uid(),nullif(concat_ws(' ',ui.name,ui.surname),''),'user','profile.unit_membership.add','profile'
 FROM public.user_info ui WHERE ui.id=auth.uid() RETURNING * INTO c;
 INSERT INTO public.client_commit_items(commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
 VALUES(c.commit_id,0,'unit_user',p_user::text,'insert','Organizer membership',ARRAY['membership']);
 PERFORM public.publish_unit_user_access_change_internal_v1(c.commit_id,p_unit,p_user);
 PERFORM public.fanout_unit_catalog_v1(c.commit_id,p_unit);
 RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object('status','applied','code',200,
  'data',jsonb_build_object('userId',p_user,'version',ver),
  'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,'commitId',c.commit_id,
   'replayed',false,'occurredAt',c.occurred_at),'sync',jsonb_build_object('replacements','[]'::jsonb)),c.commit_id);
END $$;
REVOKE ALL ON FUNCTION public.add_user_to_unit_client_sync_v1(bigint,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.add_user_to_unit_client_sync_v1(bigint,uuid,uuid) TO authenticated,service_role;


-- Source: database/functions/users/update_user.sql
CREATE OR REPLACE FUNCTION public.update_user_internal_v1(
  input_data jsonb
) RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user uuid;
  v_occasion bigint;
  v_unit_input bigint;
  v_is_manager boolean;
  v_is_editor boolean;
  v_data jsonb;
  v_email text;
  v_password text;
  v_org bigint;
  v_unit bigint;
  new_user uuid;
  existing_user_id uuid;
  v_global_before jsonb;
  v_create_response jsonb;
BEGIN
  -- Extract main fields from the input_data jsonb object
  v_user := (input_data->>'user')::uuid;
  v_occasion := (input_data->>'occasion')::bigint;
  v_unit_input := (input_data->>'unit')::bigint;
  v_is_manager := COALESCE((input_data->>'is_manager')::boolean, false);
  v_is_editor := COALESCE((input_data->>'is_editor')::boolean, false);

  -- Ensure 'data' field is a valid jsonb
  v_data := CASE
        WHEN input_data->>'data' IS NULL OR input_data->>'data' = ''
        THEN '{}'::jsonb
        ELSE input_data->'data'
       END;

  -- Determine the unit
  IF v_occasion IS NOT NULL THEN
    SELECT unit INTO v_unit FROM public.occasions WHERE id = v_occasion;
    IF v_unit IS NULL THEN
     RETURN jsonb_build_object('code', 404, 'message', 'Occasion not found');
    END IF;
  ELSIF v_unit_input IS NOT NULL THEN
    v_unit := v_unit_input;
    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = v_unit) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;
  ELSE
    RETURN jsonb_build_object('code', 400, 'message', 'Either an occasion or a unit must be provided');
  END IF;

  -- Get the organization
  SELECT organization INTO v_org FROM public.units WHERE id = v_unit;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Organization not found for the specified unit');
  END IF;

  -- Authorization check
  IF v_occasion IS NOT NULL THEN
    IF NOT public.can_manage_occasion_participants(v_occasion) THEN
     RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: Cannot manage participants for this occasion');
    END IF;
  ELSE
    IF NOT public.can_manage_unit_users(v_unit) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: Caller is not a manager for this unit');
    END IF;
  END IF;

  -- Logic for finding or creating user
  IF v_user IS NULL THEN
    v_email := lower(btrim(input_data->'data'->>'email'));

    IF v_email IS NULL OR v_email = '' THEN
      RETURN jsonb_build_object('code', 400, 'message', 'Email is required to find or create a user.');
    END IF;

    -- Share the identity allocator lock; profile identity is authoritative.
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('user-sign-in-email:' || v_org::text, 0));
    IF (SELECT count(*) FROM public.user_info WHERE organization=v_org AND lower(btrim(email_readonly))=v_email)>1 THEN
      RETURN jsonb_build_object('code',409,'message','wrong_identity'); END IF;
    SELECT id INTO existing_user_id FROM public.user_info
    WHERE organization = v_org AND lower(btrim(email_readonly)) = v_email;
    IF existing_user_id IS NULL THEN
      -- A pre-profile auth account is resolved through the same canonical format.
      SELECT id INTO existing_user_id FROM auth.users
      WHERE email = public.format_auth_email(v_org, v_email);
    END IF;

    IF existing_user_id IS NOT NULL THEN
      IF EXISTS(SELECT 1 FROM public.user_info WHERE id=existing_user_id AND organization IS DISTINCT FROM v_org) THEN
        RETURN jsonb_build_object('code',403,'message','User is outside the unit organization'); END IF;
      -- Create profile if missing
      IF NOT EXISTS (SELECT 1 FROM public.user_info WHERE id = existing_user_id) THEN
        INSERT INTO public.user_info (
          id, organization, email_readonly, data, name, surname, sex, phone,
          birth_date
        )
        VALUES (
            existing_user_id,
            v_org,
            v_email,
            v_data,
            v_data->>'name',
            v_data->>'surname',
            v_data->>'sex',
            v_data->>'phone',
            NULLIF(v_data->>'birthDate', '')::date
        );
      END IF;

      RETURN jsonb_build_object('code', 200, 'message', 'User found', 'user', existing_user_id::text);

    ELSE
      -- User does not exist, create new one
      v_password := encode(gen_random_bytes(16), 'hex');

      -- 1. Capture the JSONB response
      v_create_response := create_user_in_organization_with_data_ws(v_org, v_email, v_password, v_data);

      -- 2. Check if creation was successful (code 200)
      IF (v_create_response->>'code')::int != 200 THEN
          RETURN v_create_response; -- Return the error from the creation function
      END IF;

      -- 3. Extract the UUID string and cast it to UUID type
      new_user := (v_create_response->>'id')::uuid;

      RETURN jsonb_build_object(
       'code', 201,
       'message', 'User created successfully',
       'user', new_user::text
      );
    END IF;
  END IF;

  -- Global profile is the parent of its occasion projections.
  SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user AND organization=v_org FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',403,'message','User is outside the unit organization'); END IF;
  -- Update existing user logic
  UPDATE public.user_info
  SET
    data = COALESCE(user_info.data, '{}'::jsonb)
           || public.get_user_profile_data_patch(v_data),
    name = COALESCE(v_data->>'name', user_info.name),
    surname = COALESCE(v_data->>'surname', user_info.surname),
    sex = COALESCE(v_data->>'sex', user_info.sex),
    phone = CASE
      WHEN v_data ? 'phone' THEN v_data->>'phone'
      ELSE user_info.phone
    END,
    birth_date = CASE
      WHEN v_data ? 'birthDate'
        THEN NULLIF(v_data->>'birthDate', '')::date
      ELSE user_info.birth_date
    END
  WHERE id = v_user;

  PERFORM public.publish_user_profile_change_internal_v1(v_user,v_occasion,v_global_before);
  RETURN jsonb_build_object(
   'code', 200,
   'message', 'User details updated successfully',
   'user', v_user
  );

EXCEPTION WHEN OTHERS THEN
  IF SQLERRM = 'INVALID_USER_EMAIL' THEN
    RETURN jsonb_build_object('code', 400, 'message', SQLERRM);
  END IF;
  RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$ LANGUAGE plpgsql;

-- Unit account management remains a distinct legacy scope; occasion creation uses its command.
CREATE OR REPLACE FUNCTION public.update_user(input_data jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF input_data->>'occasion' IS NOT NULL THEN RETURN jsonb_build_object('code',426,'message','Upgrade required: create_occasion_user_client_sync_v1'); END IF;
 RETURN public.update_user_internal_v1(input_data);
END $$;
REVOKE ALL ON FUNCTION public.update_user_internal_v1(jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.update_user(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_user(jsonb) TO authenticated;
-- The obsolete three-argument occasion-profile overload is retired in contraction.sql.


-- Source: database/functions/users/update_unit_user.sql
CREATE OR REPLACE FUNCTION public.update_unit_user_internal_v1(
    input_data jsonb
) RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    -- Variables extracted from input_data
    v_user uuid;
    v_unit bigint;
    v_is_manager boolean;
    v_is_editor boolean;
    v_is_editor_view boolean;
    v_data jsonb;

    -- Internal helper variables
    v_update_user_payload jsonb;
    v_update_user_result jsonb;
    v_final_user_uuid uuid;
BEGIN
    -- 1. Extract and validate fields from the input JSONB
    v_user := (input_data->>'user')::uuid;
    v_unit := (input_data->>'unit')::bigint;
    v_is_manager := (input_data->>'is_manager')::boolean;
    v_is_editor := (input_data->>'is_editor')::boolean;
    v_is_editor_view := (input_data->>'is_editor_view')::boolean;

    -- Default the 'data' field to an empty jsonb object if it's null or an empty string
    v_data := CASE
                WHEN input_data->>'data' IS NULL OR input_data->>'data' = ''
                THEN '{}'::jsonb
                ELSE input_data->'data'
              END;

    -- 2. Perform initial validation
    IF v_unit IS NULL THEN
        RETURN jsonb_build_object('code', 400, 'message', 'The "unit" field is required.');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = v_unit) THEN
      RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;

    -- 3. Authorization Check: Verify the calling user is a manager for the specified unit
    IF NOT public.can_manage_unit_users(v_unit) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: You must be a manager of this unit.');
    END IF;

    -- 4. Prepare payload to call the update_user function
    -- The `update_user` function expects email, name, surname etc., to be inside its 'data' payload.
    -- We will ensure these fields are present in v_data before making the call.
    IF input_data ? 'name' THEN v_data := v_data || jsonb_build_object('name', input_data->>'name'); END IF;
    IF input_data ? 'surname' THEN v_data := v_data || jsonb_build_object('surname', input_data->>'surname'); END IF;
    IF input_data ? 'sex' THEN v_data := v_data || jsonb_build_object('sex', input_data->>'sex'); END IF;
    IF v_user IS NULL AND input_data ? 'email' THEN
        v_data := v_data || jsonb_build_object('email', input_data->>'email');
    END IF;

    v_update_user_payload := jsonb_build_object(
        'user', v_user,
        'unit', v_unit,
        'data', v_data
    );

    -- 5. Call update_user and handle its response
    v_update_user_result := public.update_user_internal_v1(v_update_user_payload);

    -- If the sub-function did not return a success code (200 or 201), pass its error response through.
    IF (v_update_user_result->>'code')::int NOT IN (200, 201) THEN
        RETURN v_update_user_result;
    END IF;

    -- Extract the definitive user UUID returned from the update_user function
    v_final_user_uuid := (v_update_user_result->>'user')::uuid;

    -- Sanity check in case update_user succeeds but doesn't return a UUID
    IF v_final_user_uuid IS NULL THEN
      RETURN jsonb_build_object('code', 500, 'message', 'Failed to retrieve user UUID after profile update.', 'lol', (v_update_user_result));
    END IF;

    PERFORM public.ensure_unit_membership_internal_v1(v_unit,v_final_user_uuid);

    IF EXISTS(SELECT 1 FROM public.unit_users m WHERE m.unit=v_unit AND m."user"=v_final_user_uuid
      AND (m.is_manager AND NOT coalesce(v_is_manager,false) OR m.is_editor AND NOT coalesce(v_is_editor,false)
       OR m.is_editor_view AND NOT coalesce(v_is_editor_view,false))) THEN
      PERFORM public.invalidate_member_access_invitations_internal_v1(v_unit,NULL,v_final_user_uuid);
    END IF;
    -- 6. Insert or Update the user's roles in the unit (UPSERT)
    INSERT INTO public.unit_users("user", unit, is_manager, is_editor, is_editor_view, data)
    VALUES (v_final_user_uuid, v_unit, v_is_manager, v_is_editor, v_is_editor_view, v_data)
    ON CONFLICT ("user", unit) DO UPDATE
    SET is_manager     = EXCLUDED.is_manager,
        is_editor      = EXCLUDED.is_editor,
        is_editor_view = EXCLUDED.is_editor_view,
        data           = EXCLUDED.data;

    -- 7. Return a final success response
    RETURN jsonb_build_object(
      'code', 200,
      'message', 'User role in unit updated successfully',
      'user', v_final_user_uuid::text
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'code', 500,
      'message', SQLERRM
    );
END;
$$ LANGUAGE plpgsql;
REVOKE ALL ON FUNCTION public.update_unit_user_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/people/unit_user_command.sql
-- Receipt boundary around the existing organizer-user persistence owner.
CREATE OR REPLACE FUNCTION public.save_unit_member_internal_v1(p_unit bigint,p_user uuid,p_command_id uuid,p_expected_version bigint,p_changes jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE initial jsonb; current_user_row jsonb; after_row jsonb; result jsonb; usr uuid:=p_user; ver bigint;
 c public.client_commits%ROWTYPE; intent jsonb; mode text; existing_member uuid;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,NULL,p_unit);
 IF NOT public.can_manage_unit_users(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 IF jsonb_typeof(p_changes) IS DISTINCT FROM 'object' OR octet_length(p_changes::text)>131072 THEN RAISE invalid_parameter_value USING MESSAGE='invalid organizer user'; END IF;
 mode:=p_changes->>'kind';
 IF mode='roles' THEN
  IF usr IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_changes) k WHERE k NOT IN ('kind','is_manager','is_editor','is_editor_view'))
    OR EXISTS(SELECT 1 FROM jsonb_each(p_changes-'kind') x WHERE jsonb_typeof(x.value)<>'boolean') THEN
   RAISE invalid_parameter_value USING MESSAGE='explicit organizer roles required'; END IF;
 ELSIF mode='profile' THEN
  PERFORM public.prepare_profile_change_internal_v1('{}',jsonb_build_object('profileChange',p_changes-'kind'));
 ELSIF mode IS DISTINCT FROM 'editor' THEN RAISE invalid_parameter_value USING MESSAGE='unknown organizer user intent';
 END IF;
 -- Use the same scope -> unit -> receipt order as membership add/delete.
 PERFORM pg_catalog.pg_advisory_xact_lock(-p_unit);
 initial:=public.begin_unit_client_mutation_v1(p_command_id,'profile.unit_user.save',p_unit,auth.uid(),
  encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,'user',p_user,'version',p_expected_version,'changes',p_changes)::text,'UTF8'),'sha256'),'hex'));
 IF initial->>'disposition'='replay' THEN RETURN initial->'response'; END IF;
 -- Serialize creation, update and revocation for this organizer. Existing UI
 -- callers also enter this owner through the released update_unit_user facade.
 PERFORM pg_catalog.pg_advisory_xact_lock(-p_unit);
 IF NOT public.can_manage_unit_users(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 IF usr IS NOT NULL THEN
  PERFORM 1 FROM public.user_info WHERE id=usr FOR UPDATE;
  SELECT to_jsonb(uu) INTO current_user_row FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=usr FOR UPDATE;
  IF current_user_row IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,'{}'); END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
   VALUES('unit_user','unit',p_unit,usr::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO ver FROM public.client_aggregate_versions WHERE aggregate_type='unit_user' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=usr::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM ver THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',ver,'reasonCode','version_conflict')); END IF;
 ELSE
  SELECT ui.id INTO existing_member FROM public.unit_users uu JOIN public.user_info ui ON ui.id=uu."user"
   WHERE uu.unit=p_unit AND lower(btrim(ui.email_readonly))=lower(btrim(coalesce(p_changes#>>'{data,email}',p_changes->>'email')));
  IF existing_member IS NOT NULL THEN
   SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='unit_user' AND v.scope_type='unit' AND v.scope_id=p_unit AND v.aggregate_id=existing_member::text;
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
    jsonb_build_object('userId',existing_member,'version',ver,'reasonCode','already_member')); END IF;
  IF mode<>'editor' THEN RAISE invalid_parameter_value USING MESSAGE='creation uses organizer editor'; END IF;
 END IF;
 IF mode='editor' THEN
  intent:=(p_changes-'kind')||jsonb_build_object('unit',p_unit,'user',usr);
  -- Omitted metadata must survive ordinary grid saves.
  intent:=jsonb_set(intent,'{data}',coalesce(nullif(current_user_row->'data','null'::jsonb),'{}')||coalesce(nullif(intent->'data','null'::jsonb),'{}'));
 ELSE
  intent:=coalesce(current_user_row,'{}')||jsonb_build_object('unit',p_unit,'user',usr);
  IF mode='roles' THEN intent:=intent||(p_changes-'kind');
  ELSE intent:=intent||jsonb_build_object('data',coalesce(nullif(current_user_row->'data','null'::jsonb),'{}')||(p_changes-'kind'));
  END IF;
 END IF;
 result:=public.update_unit_user_internal_v1(intent);
 IF coalesce((result->>'code')::int,500) NOT IN(200,201) THEN
  -- The legacy persistence function catches exceptions in its own subtransaction.
  RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',coalesce((result->>'code')::int,400),'{}'); END IF;
 usr:=(result->>'user')::uuid;
 SELECT to_jsonb(uu) INTO after_row FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=usr;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('unit_user','unit',p_unit,usr::text,1) ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id)
  DO UPDATE SET version=client_aggregate_versions.version+1,updated_at=clock_timestamp() RETURNING version INTO ver;
 INSERT INTO public.client_commits(unit,actor_id,actor_display,actor_kind,source,change_class)
 SELECT p_unit,auth.uid(),nullif(concat_ws(' ',ui.name,ui.surname),''),'user','profile.unit_user.save','profile' FROM public.user_info ui WHERE ui.id=auth.uid() RETURNING * INTO c;
 INSERT INTO public.client_commit_items(commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
 VALUES(c.commit_id,0,'unit_user',usr::text,CASE WHEN p_user IS NULL THEN 'insert' ELSE 'update' END,'Organizer membership',ARRAY[mode]);
 IF current_user_row->'is_manager' IS DISTINCT FROM after_row->'is_manager'
  OR current_user_row->'is_editor' IS DISTINCT FROM after_row->'is_editor'
  OR current_user_row->'is_editor_view' IS DISTINCT FROM after_row->'is_editor_view' THEN
  PERFORM public.publish_unit_user_access_change_internal_v1(c.commit_id,p_unit,usr);
 END IF;
 PERFORM public.fanout_unit_catalog_v1(c.commit_id,p_unit);
 RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object('status','applied','code',200,'data',jsonb_build_object('userId',usr,'version',ver),
  'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,'commitId',c.commit_id,'replayed',false,'occurredAt',c.occurred_at),
  'sync',jsonb_build_object('replacements','[]'::jsonb)),c.commit_id);
END $$;
REVOKE ALL ON FUNCTION public.save_unit_member_internal_v1(bigint,uuid,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Released clients use the same owner; only they may obtain an implicit baseline.
CREATE OR REPLACE FUNCTION public.update_unit_user(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE uid uuid:=(input_data->>'user')::uuid; unit_id bigint:=(input_data->>'unit')::bigint; ver bigint; result jsonb;
BEGIN
 PERFORM public.lock_people_scope_internal_v1(NULL,NULL,unit_id);
 IF NOT public.can_manage_unit_users(unit_id) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(-unit_id);
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='unit_user' AND v.scope_type='unit' AND v.scope_id=unit_id AND v.aggregate_id=uid::text;
 result:=public.save_unit_user_client_sync_v1(unit_id,uid,extensions.gen_random_uuid(),ver,(input_data-'unit'-'user')||'{"kind":"editor"}');
 RETURN jsonb_build_object('code',result->'code','user',result#>'{data,userId}');
END $$;
REVOKE ALL ON FUNCTION public.update_unit_user(jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.update_unit_user(jsonb) TO authenticated,service_role;

REVOKE ALL ON FUNCTION public.save_unit_member_internal_v1(bigint,uuid,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.save_unit_user_client_sync_v1(p_unit bigint,p_user uuid,p_command_id uuid,p_expected_version bigint,p_changes jsonb) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$ SELECT public.save_unit_member_internal_v1(p_unit,p_user,p_command_id,p_expected_version,p_changes); $$;
REVOKE ALL ON FUNCTION public.save_unit_user_client_sync_v1(bigint,uuid,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.save_unit_user_client_sync_v1(bigint,uuid,uuid,bigint,jsonb) TO authenticated,service_role;


-- Source: database/functions/users/save_profile_client_sync_v1.sql
-- Canonical profile command: receipt, version and companion effects have one owner.
CREATE OR REPLACE FUNCTION public.save_profile_internal_v1(p_occasion bigint, p_user uuid, p_command_id uuid, p_expected_version bigint, p_profile jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_before jsonb; v_after jsonb; v_result jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  PERFORM public.lock_people_scope_internal_v1(p_occasion);
  IF v_actor IS NULL OR NOT public.can_manage_occasion_participants(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object'
    OR octet_length(p_profile::text)>262144
    OR (p_profile->>'occasion')::bigint IS DISTINCT FROM p_occasion
    OR (p_profile->>'user')::uuid IS DISTINCT FROM p_user THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid occasion user profile'; END IF;
  PERFORM public.prepare_profile_change_internal_v1('{}',p_profile);
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'userId',p_user,'expectedVersion',p_expected_version,
    'profile',p_profile)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.user.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.user_info WHERE id=p_user FOR UPDATE;
  PERFORM 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=p_user FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
    'rejected',404,jsonb_build_object('version',0,'profile',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,p_user::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='occasion_user' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_user::text FOR UPDATE;
  v_before:=public.get_occasion_user_command_data_v1(p_occasion,p_user);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'profile',v_before)); END IF;
  v_result:=public.save_occasion_user_for_edit_internal_v1(
    public.prepare_profile_change_internal_v1(v_before,p_profile));
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),jsonb_build_object(
        'version',v_version,'profile',v_before,'message',v_result->>'message'));
  END IF;
  v_after:=public.get_occasion_user_command_data_v1(p_occasion,p_user);
  IF v_after IS NOT DISTINCT FROM v_before THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'profile',v_after)); END IF;
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='occasion_user'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_user::text
    RETURNING version INTO v_version;
  IF v_actor=p_user THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user,
    'payload',public.get_private_profile_payload_v1(p_occasion,p_user))); END IF;
  -- Companion-owner invalidation is part of the mutation, never a replay follow-up.
  PERFORM public.impact_companion_owners_v1(p_occasion,ARRAY[p_user],'profile.companion_identity.changed');
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.user.save','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation','update',
      'safeLabel','Occasion user','changedFields',jsonb_build_array('profile','rights','services'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
      'userId',p_user)),'[]',jsonb_build_object('version',v_version,'profile',v_after),
    '{}','[]','user',NULL,v_replacements);
END; $function$
;
REVOKE ALL ON FUNCTION public.save_profile_internal_v1(p_occasion bigint, p_user uuid, p_command_id uuid, p_expected_version bigint, p_profile jsonb) FROM PUBLIC,anon;

REVOKE ALL ON FUNCTION public.save_profile_internal_v1(bigint,uuid,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;


REVOKE ALL ON FUNCTION public.save_profile_internal_v1(bigint,uuid,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.save_profile_client_sync_v1(p_occasion bigint,p_user uuid,p_command_id uuid,p_expected_version bigint,p_profile jsonb) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$ SELECT public.save_profile_internal_v1(p_occasion,p_user,p_command_id,p_expected_version,p_profile); $$;
REVOKE ALL ON FUNCTION public.save_profile_client_sync_v1(bigint,uuid,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
