-- Source: database/functions/people/access_management.sql
CREATE OR REPLACE FUNCTION public.normalize_member_access_request_internal_v1(p_request jsonb)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public,extensions AS $$
DECLARE k text;
BEGIN
 IF jsonb_typeof(p_request) IS DISTINCT FROM 'object' OR octet_length(p_request::text)>262144
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_request) x WHERE x NOT IN ('scope','operation','communication','userId','email','expectedVersion','changes','roles','sourceDraft','predecessor')) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid_intent'; END IF;
 FOREACH k IN ARRAY ARRAY['userId','email','expectedVersion','sourceDraft','predecessor'] LOOP
  IF p_request->k='null'::jsonb THEN p_request:=p_request-k; END IF;
 END LOOP;
 IF p_request ? 'email' THEN p_request:=jsonb_set(p_request,'{email}',to_jsonb(lower(btrim(p_request->>'email')))); END IF;
 IF p_request#>>'{changes,data,email}' IS NOT NULL THEN
  p_request:=jsonb_set(p_request,'{changes,data,email}',to_jsonb(lower(btrim(p_request#>>'{changes,data,email}')))); END IF;
 IF p_request#>>'{changes,email}' IS NOT NULL THEN
  p_request:=jsonb_set(p_request,'{changes,email}',to_jsonb(lower(btrim(p_request#>>'{changes,email}')))); END IF;
 RETURN p_request||jsonb_build_object('communication',coalesce(p_request->>'communication','none'));
END $$;
REVOKE ALL ON FUNCTION public.normalize_member_access_request_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.member_access_preview_internal_v1(p_request jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE scope text:=p_request#>>'{scope,type}'; target_id bigint:=(p_request#>>'{scope,id}')::bigint;
 un bigint; org bigint; oc bigint; usr uuid:=(p_request->>'userId')::uuid; mail text; member jsonb; ver bigint:=0;
 op text:=p_request->>'operation'; communication text:=coalesce(p_request->>'communication','none');
 title text; destination text; conf jsonb; draft public.occasion_setup_drafts; existing_invitation public.access_invitations; roles jsonb:=coalesce(p_request->'roles','{}');
BEGIN
 IF NOT (public.can_manage_member_access(scope,target_id) OR communication='invite_to_accept' AND
  public.can_offer_member_access_as_actor_internal_v1(auth.uid(),scope,target_id,roles)) THEN RAISE insufficient_privilege USING MESSAGE='scope_denied'; END IF;
 IF op IS NULL OR op NOT IN ('save_member','send_invitation','save_member_and_invite') OR communication NOT IN
 ('none','participant_credentials','notify_existing_access','invite_to_accept') OR op='save_member' AND communication<>'none'
 OR communication='invite_to_accept' AND op<>'send_invitation'
 OR op='send_invitation' AND (p_request ? 'changes' OR p_request ? 'expectedVersion') THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid_intent'; END IF;
 IF scope='occasion' THEN
  SELECT unit,organization,id,o.title,'/'||o.link||'/admin' INTO un,org,oc,title,destination FROM public.occasions o WHERE id=target_id;
 ELSE
  SELECT id,organization,u.title,'/unit/'||id||'/edit' INTO un,org,title,destination FROM public.units u WHERE id=target_id;
 END IF;
 IF usr IS NOT NULL THEN
  SELECT lower(btrim(ui.email_readonly)) INTO mail FROM public.user_info ui WHERE ui.id=usr AND (ui.organization=org
   OR scope='occasion' AND EXISTS(SELECT 1 FROM public.occasion_users m WHERE m.occasion=oc AND m."user"=ui.id)
   OR scope='unit' AND EXISTS(SELECT 1 FROM public.unit_users m WHERE m.unit=un AND m."user"=ui.id));
  IF mail IS NULL THEN RAISE insufficient_privilege USING MESSAGE='wrong_identity'; END IF;
  IF p_request ? 'email' AND lower(btrim(p_request->>'email')) IS DISTINCT FROM mail THEN
   RAISE invalid_parameter_value USING MESSAGE='wrong_identity'; END IF;
 ELSE
  mail:=lower(btrim(coalesce(p_request->>'email',p_request#>>'{changes,data,email}',p_request#>>'{changes,email}')));
  IF mail IS NULL OR length(mail)>254 OR mail !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid_email'; END IF;
  IF (SELECT count(*) FROM public.user_info WHERE organization=org AND lower(btrim(email_readonly))=mail)>1 THEN
   RAISE invalid_parameter_value USING MESSAGE='wrong_identity'; END IF;
  SELECT id INTO usr FROM public.user_info WHERE organization=org AND lower(btrim(email_readonly))=mail;
 END IF;
 IF scope='unit' THEN SELECT to_jsonb(m) INTO member FROM public.unit_users m WHERE unit=un AND "user"=usr;
 ELSE SELECT to_jsonb(m) INTO member FROM public.occasion_users m WHERE occasion=oc AND "user"=usr; END IF;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type=CASE WHEN scope='unit' THEN 'unit_user' ELSE 'occasion_user' END
 AND v.scope_type=scope AND v.scope_id=target_id AND v.aggregate_id=usr::text;
 IF communication='participant_credentials' AND (scope<>'occasion' OR
   usr IS NOT NULL AND (NOT public.get_can_reset_user_password(usr) OR coalesce((member->>'is_manager')::boolean,false)
    OR coalesce((member->>'is_editor')::boolean,false) OR coalesce((member->>'is_editor_view')::boolean,false))) THEN
  RAISE insufficient_privilege USING MESSAGE='credential_operation_denied'; END IF;
 IF communication='notify_existing_access' AND (member IS NULL AND op='send_invitation') THEN
  RAISE invalid_parameter_value USING MESSAGE='membership_required'; END IF;
 IF p_request ? 'sourceDraft' THEN
  SELECT * INTO draft FROM public.occasion_setup_drafts WHERE id=(p_request->>'sourceDraft')::uuid;
  IF NOT FOUND OR draft.unit<>un OR draft.organization<>org OR (draft.data->>'finalizedOccasion')::bigint IS DISTINCT FROM oc
   OR draft.data->'sendTeamInvitations' IS DISTINCT FROM 'true'::jsonb
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(draft.data->'teamInviteEmails') e WHERE lower(btrim(e))=mail) THEN
   RAISE invalid_parameter_value USING MESSAGE='setup_invitation_not_confirmed'; END IF;
  IF roles IS DISTINCT FROM jsonb_build_object('is_editor',public.occasion_setup_invitation_role(draft.data->'teamInviteRoles',mail)='editor','is_editor_view',true) THEN
   RAISE serialization_failure USING MESSAGE='version_conflict'; END IF;
 END IF;
 IF communication='invite_to_accept' THEN
  PERFORM public.validate_access_roles_internal_v1(scope,roles);
  IF NOT EXISTS(SELECT 1 FROM jsonb_each(roles) r WHERE r.value='true') THEN
   RAISE invalid_parameter_value USING MESSAGE='roles_required'; END IF;
 END IF;
 IF op='send_invitation' AND communication='none' THEN RAISE invalid_parameter_value USING MESSAGE='communication_required'; END IF;
 IF communication='invite_to_accept' AND p_request ? 'sourceDraft' THEN
  SELECT * INTO existing_invitation FROM public.access_invitations i WHERE i.draft=(p_request->>'sourceDraft')::uuid AND i.email=mail ORDER BY i.created_at LIMIT 1;
  IF FOUND THEN
   IF existing_invitation.revoked_at IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='invitation_revoked'; END IF;
   IF existing_invitation.expires_at<=now() THEN RAISE invalid_parameter_value USING MESSAGE='invitation_expired'; END IF;
   IF existing_invitation.offered_roles IS DISTINCT FROM roles THEN RAISE serialization_failure USING MESSAGE='version_conflict'; END IF;
  END IF;
 ELSIF communication='invite_to_accept' AND NOT p_request ? 'predecessor' AND EXISTS
  (SELECT 1 FROM public.access_invitations WHERE unit=un AND occasion IS NOT DISTINCT FROM oc AND email=mail AND revoked_at IS NULL AND accepted_at IS NULL AND expires_at>now()) THEN
  NULL;
 END IF;
 -- Server-derived template facts bind preparation to both identity and intended edit.
 SELECT data INTO conf FROM public.organizations WHERE id=org;
 RETURN jsonb_build_object('actor',auth.uid(),'scope',p_request->'scope','unit',un,'occasion',oc,'organization',org,
  'userId',usr,'email',mail,'recipient',CASE WHEN communication='invite_to_accept' OR usr IS NULL THEN mail ELSE public.get_user_delivery_email(usr) END,
  'member',member,'profile',coalesce(member->'data','{}'::jsonb)||coalesce(p_request#>'{changes,data}','{}'::jsonb),'version',ver,'roles',CASE WHEN communication='invite_to_accept' THEN roles ELSE coalesce(member,'{}')||coalesce(p_request->'changes','{}') END,'changes',p_request->'changes','title',title,'destination',destination,
  'operation',op,'communication',communication,
  'pendingInvitation',communication='invite_to_accept' AND NOT p_request ? 'sourceDraft' AND NOT p_request ? 'predecessor' AND EXISTS(SELECT 1 FROM public.access_invitations i WHERE i.unit=un AND i.occasion IS NOT DISTINCT FROM oc AND i.email=mail AND i.revoked_at IS NULL AND i.accepted_at IS NULL AND i.expires_at>now()),
  'existingInvitation',CASE WHEN existing_invitation.id IS NULL THEN NULL ELSE jsonb_build_object('invitationId',existing_invitation.id,'messageId',existing_invitation.message_id) END,'organizationData',jsonb_build_object('DEFAULT_URL',conf->>'DEFAULT_URL',
   'APP_NAME',conf->>'APP_NAME','DEFAULT_LANGUAGE',coalesce(conf->>'DEFAULT_LANGUAGE','en'),'PLATFORMS',conf->'PLATFORMS'));
END $$;
REVOKE ALL ON FUNCTION public.member_access_preview_internal_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.preview_member_access(p_command_id uuid,p_request jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE preview jsonb; receipt public.client_mutation_receipts; intent_hash text;
BEGIN
 p_request:=public.normalize_member_access_request_internal_v1(p_request);
 preview:=public.member_access_preview_internal_v1(p_request);
 intent_hash:=encode(extensions.digest(p_request::text,'sha256'),'hex');
 SELECT * INTO receipt FROM public.client_mutation_receipts WHERE command_id=p_command_id;
 IF FOUND THEN
  IF receipt.actor_id IS DISTINCT FROM auth.uid() OR receipt.command_name<>'people.access.manage' OR receipt.request_sha256<>intent_hash THEN
   RAISE invalid_parameter_value USING MESSAGE='command_payload_conflict'; END IF;
  IF receipt.status='completed' THEN RETURN jsonb_build_object('replay',receipt.response); END IF;
 END IF;
 IF preview->>'pendingInvitation'='true' THEN RAISE invalid_parameter_value USING MESSAGE='invitation_pending'; END IF;
 RETURN preview||jsonb_build_object('intentHash',intent_hash,'previewHash',encode(extensions.digest(preview::text,'sha256'),'hex'));
END $$;
REVOKE ALL ON FUNCTION public.preview_member_access(uuid,jsonb) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.preview_member_access(uuid,jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.invalidate_member_access_invitations_internal_v1(p_unit bigint,p_occasion bigint,p_user uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE mail text;
BEGIN
 -- Callers retain their existing membership locks. Do not acquire a new unit
 -- lock after order/reception teardown has already locked membership rows.
 SELECT lower(btrim(email_readonly)) INTO mail FROM public.user_info WHERE id=p_user;
 UPDATE public.access_invitations SET revoked_at=clock_timestamp()
 WHERE unit=p_unit AND (p_occasion IS NULL OR occasion=p_occasion) AND email=mail AND accepted_at IS NULL AND revoked_at IS NULL;
 UPDATE public.email_messages m SET workflow_state='cancelled',last_error='invitation_revoked'
 WHERE m.workflow_state IN ('pending','blocked','preparing','retry_wait') AND EXISTS
 (SELECT 1 FROM public.access_invitations i WHERE i.message_id=m.message_id AND i.revoked_at IS NOT NULL AND i.unit=p_unit AND i.email=mail);
END $$;
REVOKE ALL ON FUNCTION public.invalidate_member_access_invitations_internal_v1(bigint,bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.manage_member_access(p_command_id uuid,p_request jsonb,p_preparation uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE preview jsonb; checked jsonb; prep public.access_email_preparations; receipt public.client_mutation_receipts;
 result jsonb; changed jsonb; invitation public.access_invitations; queued jsonb; usr uuid; scope text:=p_request#>>'{scope,type}';
 target_id bigint:=(p_request#>>'{scope,id}')::bigint; un bigint; oc bigint; org bigint; hash text; action text:=p_request->>'operation';
 comm text:=coalesce(p_request->>'communication','none'); predecessor public.access_invitations;
BEGIN
 p_request:=public.normalize_member_access_request_internal_v1(p_request);
 preview:=public.member_access_preview_internal_v1(p_request);
 un:=(preview->>'unit')::bigint; oc:=(preview->>'occasion')::bigint; org:=(preview->>'organization')::bigint;
 PERFORM public.lock_member_access_internal_v1(un);
 preview:=public.member_access_preview_internal_v1(p_request);
 hash:=encode(extensions.digest(p_request::text,'sha256'),'hex');
 INSERT INTO public.client_mutation_receipts(command_id,command_name,unit,occasion,actor_id,request_sha256)
 VALUES(p_command_id,'people.access.manage',CASE WHEN scope='unit' THEN un END,oc,auth.uid(),hash) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT receipt FROM public.client_mutation_receipts WHERE command_id=p_command_id FOR UPDATE;
 IF receipt.actor_id IS DISTINCT FROM auth.uid() OR receipt.command_name<>'people.access.manage' OR receipt.request_sha256<>hash
  OR receipt.unit IS DISTINCT FROM (CASE WHEN scope='unit' THEN un END) OR receipt.occasion IS DISTINCT FROM oc THEN
  RAISE invalid_parameter_value USING MESSAGE='command_payload_conflict'; END IF;
 IF receipt.status='completed' THEN RETURN receipt.response; END IF;
 IF preview->>'pendingInvitation'='true' THEN RAISE invalid_parameter_value USING MESSAGE='invitation_pending'; END IF;
 IF preview->'existingInvitation' IS DISTINCT FROM 'null'::jsonb AND preview ? 'existingInvitation' THEN
  result:=jsonb_build_object('status','unchanged','code',200,'data',jsonb_build_object('userId',preview->'userId',
   'access',jsonb_build_object('invitationId',preview#>'{existingInvitation,invitationId}','offered',true),
   'communication',jsonb_build_object('messageId',preview#>'{existingInvitation,messageId}','state','queued')),
   'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
   'sync',jsonb_build_object('replacements','[]'::jsonb));
  RETURN public.finish_client_mutation_v1(p_command_id,result,NULL);
 END IF;
 IF comm<>'none' THEN
  SELECT * INTO prep FROM public.access_email_preparations WHERE id=p_preparation AND actor=auth.uid()
   AND command_id=p_command_id AND intent_hash=hash AND expires_at>now() FOR UPDATE;
  IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='preparation_deferred'; END IF;
  IF prep.preview_hash IS DISTINCT FROM encode(extensions.digest(preview::text,'sha256'),'hex') THEN
   RAISE serialization_failure USING MESSAGE='version_conflict'; END IF;
 END IF;
 usr:=(preview->>'userId')::uuid;
 IF action IN ('save_member','save_member_and_invite') THEN
  -- Preserve the specialized profile/role writers and their own authorization.
  IF preview->'member' IS DISTINCT FROM 'null'::jsonb AND usr IS NOT NULL AND p_request->>'userId' IS NULL THEN
   changed:=jsonb_build_object('status','unchanged','code',200,'data',jsonb_build_object('userId',usr,'version',preview->'version','reasonCode','already_member'),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),'sync',jsonb_build_object('replacements','[]'::jsonb));
  ELSIF scope='unit' THEN
   changed:=public.save_unit_member_internal_v1(un,(p_request->>'userId')::uuid,extensions.gen_random_uuid(),
    (p_request->>'expectedVersion')::bigint,coalesce(p_request->'changes','{}')||jsonb_build_object('kind',coalesce(p_request#>>'{changes,kind}','editor')));
  ELSIF p_request->>'userId' IS NULL THEN
   changed:=public.create_occasion_member_internal_v1(oc,extensions.gen_random_uuid(),
    coalesce(p_request->'changes','{}')||jsonb_build_object('occasion',oc));
  ELSE
   changed:=public.save_profile_internal_v1(oc,usr,extensions.gen_random_uuid(),(p_request->>'expectedVersion')::bigint,
    coalesce(p_request->'changes','{}')||jsonb_build_object('occasion',oc,'user',usr));
  END IF;
  IF (changed->>'code')::int<>200 THEN
   IF comm<>'none' THEN RAISE serialization_failure USING MESSAGE='version_conflict'; END IF;
   changed:=jsonb_set(changed,'{data}',(coalesce(changed->'data','{}'::jsonb)-'message')||jsonb_build_object('reasonCode',CASE (changed->>'code')::int WHEN 403 THEN 'scope_denied' WHEN 409 THEN 'version_conflict' ELSE 'invalid_intent' END));
   changed:=jsonb_set(changed,'{mutation,commandId}',to_jsonb(p_command_id));
   changed:=jsonb_set(changed,'{mutation,receiptId}',to_jsonb(p_command_id));
   RETURN public.finish_client_mutation_v1(p_command_id,changed,NULL);
  END IF;
  usr:=coalesce((changed#>>'{data,userId}')::uuid,usr);
 END IF;
 IF p_request ? 'predecessor' THEN
  SELECT * INTO predecessor FROM public.access_invitations WHERE id=(p_request->>'predecessor')::uuid FOR UPDATE;
  IF NOT FOUND OR predecessor.unit<>un OR predecessor.occasion IS DISTINCT FROM oc OR predecessor.email<>preview->>'email' THEN
   RAISE invalid_parameter_value USING MESSAGE='wrong_identity'; END IF;
  IF EXISTS(SELECT 1 FROM public.email_messages WHERE message_id=predecessor.message_id AND workflow_state IN ('pending','preparing','sending','retry_wait','unknown')) THEN
   RAISE invalid_parameter_value USING MESSAGE='dispatch_unresolved'; END IF;
  UPDATE public.access_invitations SET revoked_at=coalesce(revoked_at,now()) WHERE id=predecessor.id;
 END IF;
 IF comm='notify_existing_access' AND NOT (CASE WHEN scope='unit' THEN EXISTS(SELECT 1 FROM public.unit_users WHERE unit=un AND "user"=usr) ELSE EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=oc AND "user"=usr) END) THEN
  RAISE invalid_parameter_value USING MESSAGE='membership_required'; END IF;
 IF comm='invite_to_accept' THEN
  IF prep.token_hash IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invalid_preparation'; END IF;
  INSERT INTO public.access_invitations(draft,scope_type,occasion,unit,organization,email,role,offered_roles,token_hash,created_by,predecessor,recipient_user)
  VALUES((p_request->>'sourceDraft')::uuid,scope,oc,un,org,preview->>'email',
   CASE WHEN (preview#>>'{roles,is_editor}')::boolean THEN 'editor' ELSE 'read_only' END,
   preview->'roles',prep.token_hash,auth.uid(),predecessor.id,usr) RETURNING * INTO invitation;
  queued:=public.enqueue_email('custom',jsonb_build_object('organization',org,'occasion',oc,'unit',un),preview->>'email',
   jsonb_build_object('invitation_id',invitation.id,'content_hash',prep.prepared->>'p_content_hash'),
   'access:'||p_command_id,'TEAM_INVITATION',now(),invitation.expires_at);
  UPDATE public.access_invitations SET message_id=(queued->>'message_id')::uuid WHERE id=invitation.id;
 ELSIF comm='participant_credentials' THEN
  queued:=public.reset_password_and_enqueue_email(usr,CASE WHEN prep.credential IS NULL THEN NULL ELSE extensions.pgp_sym_decrypt(prep.credential,(SELECT encode(secret,'hex') FROM public.access_preparation_key WHERE singleton)) END,oc,prep.prepared->'p_sealed',
   prep.prepared->>'p_content_hash','access:'||p_command_id,now()+interval '10 minutes');
 ELSIF comm='notify_existing_access' THEN
  IF usr IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_info WHERE id=usr) THEN
   RAISE invalid_parameter_value USING MESSAGE='membership_required'; END IF;
  queued:=public.enqueue_email('custom',jsonb_build_object('organization',org,'occasion',oc,'unit',un,'recipient_user',usr),
   public.get_user_delivery_email(usr),jsonb_build_object('content_hash',prep.prepared->>'p_content_hash','access_scope',scope),
   'access:'||p_command_id,'TEAM_ACCESS_NOTICE',now(),now()+interval '14 days');
 END IF;
 IF queued IS NOT NULL AND comm<>'participant_credentials' THEN
  UPDATE public.email_messages SET prepared=prep.prepared->'p_sealed',prepared_hash=encode(extensions.digest((prep.prepared->'p_sealed')::text,'sha256'),'hex'),
   prepared_at=now(),tracking_policy='disabled' WHERE message_id=(queued->>'message_id')::uuid;
  PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=(queued->>'message_id')::uuid),true);
 END IF;
 result:=coalesce(changed,jsonb_build_object('status','applied','code',200,'data','{}'::jsonb,'mutation',jsonb_build_object(
  'commandId',p_command_id,'receiptId',p_command_id,'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),'sync',jsonb_build_object('replacements','[]'::jsonb)));
 result:=jsonb_set(result,'{mutation,commandId}',to_jsonb(p_command_id));
 result:=jsonb_set(result,'{mutation,receiptId}',to_jsonb(p_command_id));
 result:=jsonb_set(result,'{data}',coalesce(result->'data','{}')||jsonb_build_object('userId',usr,
  'membership',jsonb_build_object('userId',usr,'exists',CASE WHEN scope='unit' THEN EXISTS(SELECT 1 FROM public.unit_users WHERE unit=un AND "user"=usr) ELSE EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=oc AND "user"=usr) END),
  'access',jsonb_build_object('invitationId',invitation.id,'offered',comm='invite_to_accept'),
  'communication',jsonb_build_object('messageId',queued->'message_id','state',CASE WHEN queued IS NULL THEN 'not_requested' ELSE 'queued' END)));
 DELETE FROM public.access_email_preparations WHERE id=prep.id;
 RETURN public.finish_client_mutation_v1(p_command_id,result,(changed#>>'{mutation,commitId}')::uuid);
END $$;
REVOKE ALL ON FUNCTION public.manage_member_access(uuid,jsonb,uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.manage_member_access(uuid,jsonb,uuid) TO authenticated;


-- Source: database/functions/people/access_invitations.sql
CREATE OR REPLACE FUNCTION public.access_invitation_valid_internal_v1(i public.access_invitations)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT (i.recipient_user IS NULL OR EXISTS(SELECT 1 FROM public.user_info WHERE id=i.recipient_user)) AND i.revoked_at IS NULL AND i.expires_at>now() AND public.can_offer_member_access_as_actor_internal_v1(i.created_by,i.scope_type,
  CASE WHEN i.scope_type='unit' THEN i.unit ELSE i.occasion END,i.offered_roles)
 AND EXISTS(SELECT 1 FROM public.units u WHERE u.id=i.unit AND u.organization=i.organization)
 AND (i.scope_type='unit' OR EXISTS(SELECT 1 FROM public.occasions o WHERE o.id=i.occasion AND o.unit=i.unit AND o.organization=i.organization));
$$;
REVOKE ALL ON FUNCTION public.access_invitation_valid_internal_v1(public.access_invitations) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.get_access_invitation(p_token text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE invitation public.access_invitations; result jsonb;
BEGIN
 IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN RETURN NULL; END IF;
 SELECT * INTO invitation FROM public.access_invitations WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex');
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF invitation.revoked_at IS NOT NULL THEN RETURN jsonb_build_object('reasonCode','invitation_revoked'); END IF;
 IF invitation.expires_at<=now() THEN RETURN jsonb_build_object('reasonCode','invitation_expired'); END IF;
 IF NOT public.access_invitation_valid_internal_v1(invitation) THEN RETURN NULL; END IF;
 SELECT jsonb_build_object('email',invitation.email,'title',coalesce(o.title,u.title),'unitTitle',u.title,'organization',invitation.organization,
  'scope',jsonb_build_object('type',invitation.scope_type,'id',coalesce(invitation.occasion,invitation.unit)),
  'link',CASE WHEN invitation.scope_type='unit' THEN invitation.unit::text ELSE o.link END,
  'destination',CASE WHEN invitation.scope_type='unit' THEN '/unit/'||invitation.unit||'/edit' ELSE '/'||o.link||'/admin' END,
  'roles',invitation.offered_roles,'role',invitation.role,'accepted',invitation.accepted_at IS NOT NULL,
  'existingAccount',EXISTS(SELECT 1 FROM public.user_info WHERE id=invitation.recipient_user OR invitation.recipient_user IS NULL AND organization=invitation.organization AND lower(btrim(email_readonly))=invitation.email))
 INTO result FROM public.units u LEFT JOIN public.occasions o ON o.id=invitation.occasion WHERE u.id=invitation.unit;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.get_access_invitation(text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_access_invitation(text) TO anon,authenticated;

CREATE OR REPLACE FUNCTION public.accept_access_invitation(p_token text,p_password text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE invitation public.access_invitations; recipient uuid; fresh boolean:=false; roles jsonb; un bigint;
 before_row jsonb; ver bigint; commit_row public.client_commits; projection jsonb;
BEGIN
 IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN RAISE invalid_parameter_value USING MESSAGE='invalid_invitation'; END IF;
 SELECT unit INTO un FROM public.access_invitations WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex');
 IF un IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invalid_invitation'; END IF;
 PERFORM public.lock_member_access_internal_v1(un);
 SELECT * INTO STRICT invitation FROM public.access_invitations WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex');
 IF invitation.recipient_user IS NOT NULL THEN
  SELECT id INTO recipient FROM public.user_info WHERE id=invitation.recipient_user;
  IF recipient IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invitation_revoked'; END IF;
 ELSE
  IF (SELECT count(*) FROM public.user_info WHERE organization=invitation.organization AND lower(btrim(email_readonly))=invitation.email)>1 THEN
   RAISE insufficient_privilege USING MESSAGE='wrong_identity'; END IF;
  SELECT id INTO recipient FROM public.user_info WHERE organization=invitation.organization AND lower(btrim(email_readonly))=invitation.email;
 END IF;
 -- Legacy order/reception teardown owns its membership row before invalidating
 -- offers. Take that same row before the invitation row to avoid an inverted
 -- lock order while retaining the canonical unit/identity locks for creation.
 IF recipient IS NOT NULL THEN
  IF invitation.scope_type='unit' THEN
   PERFORM 1 FROM public.unit_users WHERE unit=un AND "user"=recipient FOR UPDATE;
  ELSE
   PERFORM 1 FROM public.occasion_users WHERE occasion=invitation.occasion AND "user"=recipient FOR UPDATE;
  END IF;
 END IF;
 SELECT * INTO STRICT invitation FROM public.access_invitations WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex') FOR UPDATE;
 IF invitation.revoked_at IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='invitation_revoked'; END IF;
 IF invitation.expires_at<=now() THEN RAISE invalid_parameter_value USING MESSAGE='invitation_expired'; END IF;
 IF NOT public.access_invitation_valid_internal_v1(invitation) THEN RAISE insufficient_privilege USING MESSAGE='scope_denied'; END IF;
 -- Fence live inviter authorization against concurrent revocation.
 PERFORM 1 FROM public.unit_users WHERE unit=un AND "user"=invitation.created_by FOR SHARE;
 PERFORM 1 FROM public.organization_users WHERE organization=invitation.organization AND "user"=invitation.created_by FOR SHARE;
 IF invitation.occasion IS NOT NULL THEN PERFORM 1 FROM public.occasion_users WHERE occasion=invitation.occasion AND "user"=invitation.created_by FOR SHARE; END IF;
 IF NOT public.access_invitation_valid_internal_v1(invitation) THEN RAISE insufficient_privilege USING MESSAGE='scope_denied'; END IF;
 IF invitation.recipient_user IS NOT NULL THEN
  SELECT id INTO recipient FROM public.user_info WHERE id=invitation.recipient_user;
  IF recipient IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='invitation_revoked'; END IF;
 ELSE
  IF (SELECT count(*) FROM public.user_info WHERE organization=invitation.organization AND lower(btrim(email_readonly))=invitation.email)>1 THEN
   RAISE insufficient_privilege USING MESSAGE='wrong_identity'; END IF;
  SELECT id INTO recipient FROM public.user_info WHERE organization=invitation.organization AND lower(btrim(email_readonly))=invitation.email;
 END IF;
 IF invitation.accepted_at IS NOT NULL THEN
  IF auth.uid() IS DISTINCT FROM invitation.accepted_by THEN RAISE insufficient_privilege USING MESSAGE='wrong_identity'; END IF;
  RETURN public.get_access_invitation(p_token)||jsonb_build_object('accepted',true,'newAccount',false);
 END IF;
 IF recipient IS NOT NULL THEN
  IF auth.uid() IS DISTINCT FROM recipient THEN RAISE insufficient_privilege USING MESSAGE='wrong_identity'; END IF;
 ELSE
  IF auth.uid() IS NOT NULL THEN RAISE insufficient_privilege USING MESSAGE='wrong_identity'; END IF;
  IF p_password IS NULL OR length(p_password)<8 OR octet_length(p_password)>1024 THEN RAISE invalid_parameter_value USING MESSAGE='invalid_password'; END IF;
  recipient:=public.create_user_in_organization_with_data_pure(invitation.organization,invitation.email,p_password,'{}');
  fresh:=true;
 END IF;
 roles:=invitation.offered_roles;
 PERFORM public.validate_access_roles_internal_v1(invitation.scope_type,roles);
 IF invitation.scope_type='unit' THEN
  SELECT to_jsonb(m) INTO before_row FROM public.unit_users m WHERE unit=un AND "user"=recipient FOR UPDATE;
  INSERT INTO public.unit_users(unit,"user",is_manager,is_editor,is_editor_view)
  VALUES(un,recipient,coalesce((roles->>'is_manager')::boolean,false),coalesce((roles->>'is_editor')::boolean,false),coalesce((roles->>'is_editor_view')::boolean,false))
  ON CONFLICT(unit,"user") DO UPDATE SET is_manager=coalesce(public.unit_users.is_manager,false) OR excluded.is_manager,
   is_editor=coalesce(public.unit_users.is_editor,false) OR excluded.is_editor,
   is_editor_view=coalesce(public.unit_users.is_editor_view,false) OR excluded.is_editor_view;
 ELSE
  SELECT to_jsonb(m) INTO before_row FROM public.occasion_users m WHERE occasion=invitation.occasion AND "user"=recipient FOR UPDATE;
  INSERT INTO public.occasion_users(occasion,"user",data) SELECT invitation.occasion,recipient,
   jsonb_build_object('name',ui.name,'surname',ui.surname,'email',ui.email_readonly) FROM public.user_info ui WHERE ui.id=recipient
  ON CONFLICT(occasion,"user") DO NOTHING;
  UPDATE public.occasion_users SET
   is_manager=coalesce(is_manager,false) OR coalesce((roles->>'is_manager')::boolean,false),
   is_editor=coalesce(is_editor,false) OR coalesce((roles->>'is_editor')::boolean,false),
   is_editor_view=coalesce(is_editor_view,false) OR coalesce((roles->>'is_editor_view')::boolean,false),
   is_editor_order=coalesce(is_editor_order,false) OR coalesce((roles->>'is_editor_order')::boolean,false),
   is_editor_order_view=coalesce(is_editor_order_view,false) OR coalesce((roles->>'is_editor_order_view')::boolean,false),
   is_receptionist=coalesce(is_receptionist,false) OR coalesce((roles->>'is_receptionist')::boolean,false),
   is_approver=coalesce(is_approver,false) OR coalesce((roles->>'is_approver')::boolean,false),
   is_cleaning_crew=coalesce(is_cleaning_crew,false) OR coalesce((roles->>'is_cleaning_crew')::boolean,false),
   is_cleaning_blocked=coalesce(is_cleaning_blocked,false) OR coalesce((roles->>'is_cleaning_blocked')::boolean,false)
  WHERE occasion=invitation.occasion AND "user"=recipient;
 END IF;
 UPDATE public.access_invitations SET recipient_user=recipient,accepted_by=recipient,accepted_at=clock_timestamp() WHERE id=invitation.id;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES(CASE WHEN invitation.scope_type='unit' THEN 'unit_user' ELSE 'occasion_user' END,invitation.scope_type,
  coalesce(invitation.occasion,un),recipient::text,1)
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp()
 RETURNING version INTO ver;
 IF invitation.scope_type='occasion' THEN
  PERFORM public.record_client_sync_commit_v1(invitation.occasion,'profile.team_invitation.accept','profile',
   jsonb_build_array(jsonb_build_object('entityType','occasion_user','entityId',recipient,'operation',CASE WHEN before_row IS NULL THEN 'insert' ELSE 'update' END,
   'safeLabel','Team invitation accepted','changedFields',jsonb_build_array('membership','rights'))),'{}'::text[],
   jsonb_build_array(jsonb_build_object('component','private_profile','userId',recipient)),'[]',
   CASE WHEN auth.uid() IS NULL THEN 'unknown' ELSE 'user' END,'Invited member accepted');
 ELSE
  INSERT INTO public.client_commits(unit,actor_id,actor_kind,source,change_class)
  VALUES(un,recipient,'user','profile.team_invitation.accept','profile') RETURNING * INTO commit_row;
  INSERT INTO public.client_commit_items(commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES(commit_row.commit_id,0,'unit_user',recipient::text,'update','Team invitation accepted',ARRAY['membership','rights']);
  PERFORM public.publish_unit_user_access_change_internal_v1(commit_row.commit_id,un,recipient);
  PERFORM public.fanout_unit_catalog_v1(commit_row.commit_id,un);
 END IF;
 RETURN public.get_access_invitation(p_token)||jsonb_build_object('accepted',true,'newAccount',fresh);
END $$;
REVOKE ALL ON FUNCTION public.accept_access_invitation(text,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.accept_access_invitation(text,text) TO anon,authenticated;

CREATE OR REPLACE FUNCTION public.revoke_access_invitation(p_invitation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE invitation public.access_invitations;
BEGIN
 SELECT * INTO STRICT invitation FROM public.access_invitations WHERE id=p_invitation;
 IF NOT public.can_offer_member_access_as_actor_internal_v1(auth.uid(),invitation.scope_type,coalesce(invitation.occasion,invitation.unit),invitation.offered_roles) THEN RAISE insufficient_privilege USING MESSAGE='scope_denied'; END IF;
 PERFORM public.lock_member_access_internal_v1(invitation.unit);
 SELECT * INTO STRICT invitation FROM public.access_invitations WHERE id=p_invitation FOR UPDATE;
 IF NOT public.can_offer_member_access_as_actor_internal_v1(auth.uid(),invitation.scope_type,coalesce(invitation.occasion,invitation.unit),invitation.offered_roles) THEN RAISE insufficient_privilege USING MESSAGE='scope_denied'; END IF;
 UPDATE public.access_invitations SET revoked_at=coalesce(revoked_at,clock_timestamp()) WHERE id=p_invitation AND accepted_at IS NULL;
 UPDATE public.email_messages SET workflow_state='cancelled',last_error='invitation_revoked'
 WHERE message_id=invitation.message_id AND invitation.accepted_at IS NULL AND workflow_state IN ('pending','blocked','preparing','retry_wait');
 RETURN jsonb_build_object('revoked',invitation.accepted_at IS NULL,'accepted',invitation.accepted_at IS NOT NULL);
END $$;
REVOKE ALL ON FUNCTION public.revoke_access_invitation(uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.revoke_access_invitation(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_member_access_status(p_scope text,p_id bigint,p_user uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb;
BEGIN
 IF NOT public.can_manage_member_access(p_scope,p_id) THEN RAISE insufficient_privilege USING MESSAGE='scope_denied'; END IF;
 SELECT jsonb_build_object('invitations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',i.id,'email',i.email,'roles',i.offered_roles,
  'acceptedAt',i.accepted_at,'revokedAt',i.revoked_at,'expiresAt',i.expires_at,'messageId',i.message_id)) FROM public.access_invitations i
  WHERE (p_scope='unit' AND i.scope_type='unit' AND i.unit=p_id OR p_scope='occasion' AND i.occasion=p_id)
  AND (p_user IS NULL OR i.recipient_user=p_user OR i.email=(SELECT lower(btrim(email_readonly)) FROM public.user_info WHERE id=p_user))),'[]'),
  'messages',coalesce((SELECT jsonb_agg(jsonb_build_object('messageId',m.message_id,'userId',m.recipient_user,'recipient',m.recipient,'code',m.code,
   'state',CASE WHEN m.workflow_state='unknown' THEN 'dispatch_unresolved' WHEN m.bounced_at IS NOT NULL OR m.provider_failure IN ('reject','rendering_failure') THEN 'failed' WHEN m.workflow_state='accepted' THEN CASE WHEN m.delivered_at IS NOT NULL THEN 'delivered' ELSE 'provider_accepted' END
    WHEN m.workflow_state IN ('pending','blocked','preparing','sending','retry_wait','unknown') THEN 'queued'
    WHEN m.workflow_state='dead' THEN 'failed' ELSE m.workflow_state END,'providerAcceptedAt',m.accepted_at,'deliveredAt',m.delivered_at))
   FROM public.email_messages m WHERE (p_scope='unit' AND m.occasion IS NULL AND m.unit=p_id OR p_scope='occasion' AND m.occasion=p_id)
   AND m.code IN ('SIGN_IN_CODE','TEAM_ACCESS_NOTICE','TEAM_INVITATION') AND (p_user IS NULL OR m.recipient_user=p_user OR EXISTS
    (SELECT 1 FROM public.access_invitations i WHERE i.message_id=m.message_id AND i.email=(SELECT lower(btrim(email_readonly)) FROM public.user_info WHERE id=p_user)))),'[]')) INTO result;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.get_member_access_status(text,bigint,uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.get_member_access_status(text,bigint,uuid) TO authenticated;

-- Published link/RPC adapters for installed clients; retire only after link expiry
-- and enforced upgrade. The public /team-invitation path remains unchanged.
CREATE OR REPLACE FUNCTION public.get_occasion_team_invitation(p_token text) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$ SELECT CASE WHEN r ? 'reasonCode' OR r#>>'{scope,type}'='unit' THEN NULL ELSE r END FROM (SELECT public.get_access_invitation(p_token) r) v; $$;
CREATE OR REPLACE FUNCTION public.accept_occasion_team_invitation(p_token text,p_password text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.access_invitations WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex') AND scope_type='unit') THEN
  RAISE invalid_parameter_value USING MESSAGE='upgrade_required'; END IF;
 RETURN public.accept_access_invitation(p_token,p_password);
END $$;
REVOKE ALL ON FUNCTION public.get_occasion_team_invitation(text),public.accept_occasion_team_invitation(text,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_occasion_team_invitation(text),public.accept_occasion_team_invitation(text,text) TO anon,authenticated;

CREATE OR REPLACE FUNCTION public.resend_access_invitation(p_invitation uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE i public.access_invitations;
BEGIN
 SELECT * INTO STRICT i FROM public.access_invitations WHERE id=p_invitation;
 IF NOT public.can_offer_member_access_as_actor_internal_v1(auth.uid(),i.scope_type,coalesce(i.occasion,i.unit),i.offered_roles) THEN RAISE insufficient_privilege USING MESSAGE='scope_denied'; END IF;
 IF EXISTS(SELECT 1 FROM public.email_messages WHERE message_id=i.message_id AND workflow_state IN ('pending','preparing','sending','retry_wait','unknown')) THEN
  RAISE invalid_parameter_value USING MESSAGE='dispatch_unresolved'; END IF;
 RETURN jsonb_build_object('scope',jsonb_build_object('type',i.scope_type,'id',coalesce(i.occasion,i.unit)),
  'operation','send_invitation','communication','invite_to_accept','email',i.email,'roles',i.offered_roles,'predecessor',i.id);
END $$;
REVOKE ALL ON FUNCTION public.resend_access_invitation(uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.resend_access_invitation(uuid) TO authenticated;


-- Source: database/functions/users/save_occasion_user_for_edit.sql
CREATE OR REPLACE FUNCTION public.save_occasion_user_for_edit_internal_v1(input_data jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion bigint := (input_data->>'occasion')::bigint;
    v_user uuid := (input_data->>'user')::uuid;
    v_unit bigint;
    v_data jsonb := CASE WHEN jsonb_typeof(input_data->'data') = 'object'
                         THEN (input_data->'data')-'is_invited' ELSE '{}'::jsonb END;
    v_services jsonb := CASE WHEN jsonb_typeof(input_data->'services') = 'object'
                             THEN input_data->'services' ELSE '{}'::jsonb END;
    v_catalog jsonb;
    v_existing_services jsonb;
    v_code text;
    v_global_before jsonb;
BEGIN
    SELECT o.unit,
           CASE WHEN jsonb_typeof(o.services) = 'object'
                THEN o.services ELSE '{}'::jsonb END
      INTO v_unit, v_catalog
      FROM public.occasions o
     WHERE o.id = v_occasion;

    IF v_unit IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion not found');
    END IF;

    -- Keep the write boundary at occasion management level. In particular,
    -- a unit editor must not gain the ability to assign manager/editor flags
    -- through this SECURITY DEFINER function.
    IF NOT public.can_manage_occasion_participants(v_occasion) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Not authorized to update occasion users');
    END IF;

    SELECT CASE WHEN jsonb_typeof(ou.services) = 'object'
                THEN ou.services ELSE '{}'::jsonb END
      INTO v_existing_services
      FROM public.occasion_users ou
     WHERE ou.occasion = v_occasion AND ou."user" = v_user;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion user not found');
    END IF;

    -- Every assigned accommodation code must still exist in this occasion's
    -- catalog. This keeps the grid select and persisted service data aligned.
    FOR v_code IN
        SELECT key FROM jsonb_each(
            CASE WHEN jsonb_typeof(v_services->'accommodation') = 'object'
                 THEN v_services->'accommodation' ELSE '{}'::jsonb END
        )
    LOOP
        IF NOT EXISTS (
            SELECT 1
              FROM jsonb_array_elements(
                  CASE WHEN jsonb_typeof(v_catalog->'accommodation') = 'array'
                       THEN v_catalog->'accommodation' ELSE '[]'::jsonb END
              ) item
             WHERE item->>'code' = v_code
        ) AND NOT COALESCE((
            -- Historical assignments can outlive a removed catalog item.
            -- Preserve such a code on unrelated edits, but never allow a new
            -- unknown code to be introduced.
            jsonb_typeof(v_existing_services->'accommodation') = 'object'
            AND (v_existing_services->'accommodation') ? v_code
        ), false) THEN
            RETURN jsonb_build_object('code', 400, 'message', 'Unknown accommodation code: ' || v_code);
        END IF;
    END LOOP;

    SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user FOR UPDATE;
    UPDATE public.user_info
       SET data = COALESCE(user_info.data, '{}'::jsonb)
                  || public.get_user_profile_data_patch(v_data),
           name = COALESCE(v_data->>'name', user_info.name),
           surname = COALESCE(v_data->>'surname', user_info.surname),
           sex = COALESCE(v_data->>'sex', user_info.sex),
           phone = CASE
               WHEN v_data ? 'phone' THEN v_data->>'phone'
               ELSE user_info.phone
           END,
           birth_date = CASE
               WHEN v_data ? 'birthDate'
                   THEN NULLIF(v_data->>'birthDate', '')::date
               ELSE user_info.birth_date
           END
     WHERE id = v_user;

    PERFORM public.publish_user_profile_change_internal_v1(v_user,v_occasion,v_global_before);

    IF EXISTS(SELECT 1 FROM public.occasion_users m WHERE m.occasion=v_occasion AND m."user"=v_user
     AND EXISTS(SELECT 1 FROM jsonb_each(to_jsonb(m)) r WHERE r.key IN ('is_manager','is_editor','is_editor_view','is_editor_order','is_editor_order_view','is_receptionist','is_approver','is_cleaning_crew') AND r.value='true' AND input_data->r.key='false')) THEN
      PERFORM public.invalidate_member_access_invitations_internal_v1(v_unit,v_occasion,v_user);
    END IF;
    UPDATE public.occasion_users
       SET data = v_data,
           -- A grid may edit only one service family. Merge top-level service
           -- keys so changing accommodation never erases food (and vice versa).
           -- An explicitly supplied empty object still clears that family.
           services = COALESCE(occasion_users.services, '{}'::jsonb) || v_services,
           role = CASE WHEN input_data ? 'role' THEN (input_data->>'role')::int ELSE role END,
           is_editor = COALESCE((input_data->>'is_editor')::boolean, is_editor),
           is_editor_view = COALESCE((input_data->>'is_editor_view')::boolean, is_editor_view),
           is_editor_order = COALESCE((input_data->>'is_editor_order')::boolean, is_editor_order),
           is_editor_order_view = COALESCE((input_data->>'is_editor_order_view')::boolean, is_editor_order_view),
           is_cleaning_crew = COALESCE((input_data->>'is_cleaning_crew')::boolean, is_cleaning_crew),
           is_cleaning_blocked = COALESCE((input_data->>'is_cleaning_blocked')::boolean, is_cleaning_blocked),
           is_receptionist = COALESCE((input_data->>'is_receptionist')::boolean, is_receptionist),
           is_approver = COALESCE((input_data->>'is_approver')::boolean, is_approver),
           is_approved = COALESCE((input_data->>'is_approved')::boolean, is_approved),
           is_manager = COALESCE((input_data->>'is_manager')::boolean, is_manager)
     WHERE occasion = v_occasion AND "user" = v_user;

    RETURN jsonb_build_object('code', 200, 'message', 'Occasion user updated');
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;

-- Released grid facade. Baseline is read under the membership lock.
CREATE OR REPLACE FUNCTION public.save_occasion_user_for_edit(input_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE oc bigint:=(input_data->>'occasion')::bigint; usr uuid:=(input_data->>'user')::uuid; ver bigint; r jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT(public.can_manage_occasion_participants(oc)) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_people_scope_internal_v1(oc);
 PERFORM 1 FROM public.user_info WHERE id=usr FOR UPDATE;
 PERFORM 1 FROM public.occasion_users WHERE occasion=oc AND "user"=usr FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=usr::text;
 input_data:=jsonb_set(input_data,'{data}',CASE WHEN jsonb_typeof(input_data->'data')='object' THEN (input_data->'data')-'is_invited' ELSE '{}' END);
 r:=public.save_profile_client_sync_v1(oc,usr,extensions.gen_random_uuid(),ver,input_data);
 RETURN jsonb_build_object('code',r->'code','message',r#>'{data,message}');
END $$;
REVOKE ALL ON FUNCTION public.save_occasion_user_for_edit_internal_v1(jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.save_occasion_user_for_edit(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_occasion_user_for_edit(jsonb) TO authenticated;


-- Source: database/functions/users/unit_access_deletion.sql
-- Canonical owner recovered from the recorded effective main schema.
-- Public signatures, response envelopes and existing execution roles are preserved.

CREATE OR REPLACE FUNCTION public.delete_unit_user_internal_v1(usr uuid, unit_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    IF NOT public.can_manage_unit_users(unit_id) THEN
      RAISE insufficient_privilege USING MESSAGE='unit manager required';
    END IF;
    PERFORM public.invalidate_member_access_invitations_internal_v1(unit_id,NULL,usr);
    DELETE FROM unit_users
    WHERE "user" = usr AND unit = unit_id;

    UPDATE occasion_users
    SET is_editor = false,
        is_manager = false,
        is_editor_view = false
    WHERE "user" = usr
      AND occasion IN (SELECT id FROM occasions WHERE unit = unit_id);

    RETURN jsonb_build_object('code', 200);
END;
$function$
;
REVOKE ALL ON FUNCTION public.delete_unit_user_internal_v1(uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public.delete_unit_user_internal_v1(uuid,bigint) TO postgres;

CREATE OR REPLACE FUNCTION public.delete_unit_user_client_sync_v1(p_user uuid, p_unit bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_before jsonb;
  v_after jsonb; v_result jsonb; v_commit public.client_commits%ROWTYPE;

BEGIN
  IF v_actor IS NULL OR p_user IS NULL
    OR NOT public.can_manage_unit_users(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  PERFORM public.lock_people_scope_internal_v1(NULL,NULL,p_unit);
  PERFORM pg_catalog.pg_advisory_xact_lock(-p_unit);
  IF NOT public.can_manage_unit_users(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'unit',p_unit,'userId',p_user)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'profile.unit_access.delete',p_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT jsonb_build_object('unitUser',(SELECT to_jsonb(uu)
      FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=p_user),
    'occasionUsers',COALESCE((SELECT jsonb_agg(to_jsonb(ou) ORDER BY ou.occasion)
      FROM public.occasion_users ou JOIN public.occasions o ON o.id=ou.occasion
      WHERE o.unit=p_unit AND ou."user"=p_user),'[]'::jsonb)) INTO v_before;
  v_result:=public.delete_unit_user_internal_v1(p_user,p_unit);
  SELECT jsonb_build_object('unitUser',(SELECT to_jsonb(uu)
      FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=p_user),
    'occasionUsers',COALESCE((SELECT jsonb_agg(to_jsonb(ou) ORDER BY ou.occasion)
      FROM public.occasion_users ou JOIN public.occasions o ON o.id=ou.occasion
      WHERE o.unit=p_unit AND ou."user"=p_user),'[]'::jsonb)) INTO v_after;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('userId',p_user)); END IF;
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT p_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'profile.unit_access.delete','profile' FROM public.user_info ui
    WHERE ui.id=v_actor RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'unit_user',p_user::text,'delete','Unit access',
    ARRAY['rights']);
  PERFORM public.publish_unit_user_access_change_internal_v1(v_commit.commit_id,p_unit,p_user);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('userId',p_user),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $function$
;
REVOKE ALL ON FUNCTION public.delete_unit_user_client_sync_v1(uuid,bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public.delete_unit_user_client_sync_v1(uuid,bigint,uuid) TO postgres,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.delete_unit_user(usr uuid, unit_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_response jsonb;
BEGIN
  v_response:=public.delete_unit_user_client_sync_v1(
    usr,unit_id,extensions.gen_random_uuid());
  RETURN jsonb_build_object('code',(v_response->>'code')::integer)
    ||COALESCE(v_response->'data','{}'::jsonb);
END; $function$
;
REVOKE ALL ON FUNCTION public.delete_unit_user(uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public.delete_unit_user(uuid,bigint) TO postgres,authenticated,service_role;


-- Source: database/functions/groups/remove_occasion_user_domain.sql
-- One occasion-user teardown handler. Authorization and receipt belong to its callers.
CREATE OR REPLACE FUNCTION public.remove_occasion_user_domain_internal_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE groups bigint[]; impacts jsonb;
BEGIN
 PERFORM public.invalidate_member_access_invitations_internal_v1((SELECT unit FROM public.occasions WHERE id=p_occasion),p_occasion,p_user);
 PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
 SELECT COALESCE(array_agg(DISTINCT g.id),'{}') INTO groups FROM public.user_group_info g LEFT JOIN public.user_groups ug ON g.id=ug."group" WHERE g.occasion=p_occasion AND (ug."user"=p_user OR g.leader=p_user);
 impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(SELECT "user" FROM public.user_groups WHERE "group"=ANY(groups))||ARRAY[p_user]);
 impacts:=(SELECT COALESCE(jsonb_agg(x),'[]') FROM jsonb_array_elements(impacts) x WHERE x->>'userId'<>p_user::text)||public.remove_user_activity_internal_v1(p_occasion,ARRAY[p_user]);
 UPDATE public.news SET created_by=NULL WHERE created_by=p_user AND occasion=p_occasion;
 UPDATE public.user_group_info SET leader=NULL WHERE occasion=p_occasion AND leader=p_user;
 DELETE FROM public.user_groups WHERE "user"=p_user AND "group"=ANY(groups);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'user_group','occasion',p_occasion,id::text,1 FROM unnest(groups) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 DELETE FROM public.event_users WHERE "user"=p_user AND event IN(SELECT id FROM public.events WHERE occasion=p_occasion);
 DELETE FROM public.event_users_saved WHERE "user"=p_user AND event IN(SELECT id FROM public.events WHERE occasion=p_occasion);
 DELETE FROM public.user_news WHERE "user"=p_user AND occasion=p_occasion;
 -- Membership attention belongs to the deleted application, not the account.
 PERFORM public.notification_center_prepared_delete_events(ARRAY(SELECT e.id FROM public.notification_center_events e JOIN public.occasions o ON o.id=p_occasion AND o.organization=e.organization
  WHERE e.occasion=p_occasion AND e.kind='occasion_joined' AND e.data->>'userId'=p_user::text));
 DELETE FROM public.notification_center_events e
 USING public.occasions o
 WHERE o.id=p_occasion AND e.organization=o.organization AND e.occasion=o.id
   AND e.kind='occasion_joined' AND e.data->>'userId'=p_user::text;
 DELETE FROM public.occasion_users WHERE "user"=p_user AND occasion=p_occasion;
 DELETE FROM public.client_sync_private_scopes WHERE occasion=p_occasion AND user_id=p_user;
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_user::text;
 RETURN impacts;
END $$;
REVOKE ALL ON FUNCTION public.remove_occasion_user_domain_internal_v1(bigint,uuid) FROM PUBLIC,anon,authenticated;


-- Source: database/functions/occasion_setup/invitations.sql
-- Setup selects confirmed recipients; the people owner executes their commands.
CREATE OR REPLACE FUNCTION public.normalize_occasion_setup_invite_emails(p_emails text[])
RETURNS text[] LANGUAGE plpgsql IMMUTABLE SET search_path=public,extensions AS $$
DECLARE result text[];
BEGIN
 IF coalesce(cardinality(p_emails),0)>20 THEN RAISE invalid_parameter_value USING MESSAGE='At most 20 invitations'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(p_emails) e WHERE e IS NULL OR length(btrim(e))>254
   OR btrim(e) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid invitation email'; END IF;
 SELECT coalesce(array_agg(e ORDER BY e),'{}'::text[]) INTO result
 FROM (SELECT DISTINCT lower(btrim(e)) e FROM unnest(p_emails) e) normalized;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.normalize_occasion_setup_invite_emails(text[]) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.occasion_setup_invitation_role(p_roles jsonb,p_email text)
RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public,extensions AS $$
BEGIN
 IF p_roles IS NOT NULL AND (jsonb_typeof(p_roles) IS DISTINCT FROM 'object') THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid invitation roles'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each_text(coalesce(p_roles,'{}')) r
   WHERE r.key<>lower(btrim(r.key)) OR r.value IS NULL OR r.value NOT IN ('editor','read_only')) THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid invitation role'; END IF;
 RETURN coalesce(p_roles->>p_email,'editor');
END $$;
REVOKE ALL ON FUNCTION public.occasion_setup_invitation_role(jsonb,text) FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.preview_occasion_setup_invitations(p_id uuid,p_emails text[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE d public.occasion_setup_drafts; emails text[]; event_id bigint; event_link text; event_title text; recipients jsonb; org_data jsonb;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT public.can_create_occasion(d.unit) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF NOT public.get_is_manager_on_unit(d.unit) THEN RETURN jsonb_build_object('canManage',false,'recipients','[]'::jsonb); END IF;
 IF p_emails IS NULL THEN
  IF d.data ? 'finalizedOccasion' AND d.data->'sendTeamInvitations' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE invalid_parameter_value USING MESSAGE='Invitation sending not confirmed'; END IF;
  IF jsonb_typeof(coalesce(d.data->'teamInviteEmails','[]'::jsonb)) IS DISTINCT FROM 'array' THEN
   RAISE invalid_parameter_value USING MESSAGE='Invalid invitation emails'; END IF;
  p_emails:=ARRAY(SELECT jsonb_array_elements_text(coalesce(d.data->'teamInviteEmails','[]'::jsonb)));
 END IF;
 emails:=public.normalize_occasion_setup_invite_emails(p_emails);
 event_id:=(d.data->>'finalizedOccasion')::bigint;
 IF event_id IS NOT NULL THEN SELECT link,title INTO event_link,event_title FROM public.occasions WHERE id=event_id AND unit=d.unit AND organization=d.organization;
 ELSE event_link:=d.data->>'link'; event_title:=d.data->>'title'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('email',e,'kind',CASE WHEN EXISTS(
   SELECT 1 FROM public.unit_users uu WHERE uu.unit=d.unit AND uu."user"=ui.id) THEN 'member'
   WHEN ui.id IS NOT NULL THEN 'account' ELSE 'new' END,
   'role',public.occasion_setup_invitation_role(d.data->'teamInviteRoles',e),
   'alreadyEditor',coalesce((SELECT ou.is_editor OR ou.is_manager OR (ou.is_editor_view AND public.occasion_setup_invitation_role(d.data->'teamInviteRoles',e)='read_only') FROM public.occasion_users ou
      WHERE ou.occasion=event_id AND ou."user"=ui.id),false)) ORDER BY e),'[]')
 INTO recipients FROM unnest(emails) e LEFT JOIN public.user_info ui
 ON ui.organization=d.organization AND lower(btrim(ui.email_readonly))=e;
 SELECT jsonb_build_object('APP_NAME',data->>'APP_NAME','DEFAULT_URL',data->>'DEFAULT_URL') INTO org_data FROM public.organizations WHERE id=d.organization;
 RETURN jsonb_build_object('canManage',true,'sendConfirmed',d.data->'sendTeamInvitations'='true'::jsonb,'recipients',recipients,'event',jsonb_build_object(
   'id',event_id,'link',event_link,'title',event_title,'unit',d.unit,'organization',d.organization),
   'organizationData',org_data);
END $$;
REVOKE ALL ON FUNCTION public.preview_occasion_setup_invitations(uuid,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.preview_occasion_setup_invitations(uuid,text[]) TO authenticated;


-- Source: database/functions/users/get_occasion_users_for_edit.sql
-- Historical SMTP invitation hints are a readonly compatibility projection, never canonical delivery evidence.
CREATE OR REPLACE FUNCTION public.get_occasion_sign_in_email_statuses(
  p_occasion bigint
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.can_read_occasion_directory(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  WITH evidence AS (
    SELECT le.recipient_user AS "user",le.created_at AS sent_at
    FROM public.log_emails le
    JOIN public.email_templates et ON et.id::text = le.template
    WHERE le.occasion = p_occasion
      AND le.recipient_user IS NOT NULL
      AND et.code = 'SIGN_IN_CODE'
    UNION ALL
    SELECT m.recipient_user,m.accepted_at FROM public.email_messages m
    WHERE m.occasion=p_occasion AND (m.message_kind='sign_in' OR (m.message_kind='custom' AND m.code='TEAM_ACCESS_NOTICE'))
      AND m.recipient_user IS NOT NULL AND m.accepted_at IS NOT NULL
    UNION ALL
    SELECT i.accepted_by,m.accepted_at FROM public.access_invitations i
    JOIN public.email_messages m ON m.message_id=i.message_id
    WHERE i.occasion=p_occasion AND i.accepted_by IS NOT NULL AND m.accepted_at IS NOT NULL
  ), accepted AS (
    SELECT "user",count(*)::integer send_count,min(sent_at) first_sent_at,max(sent_at) last_sent_at FROM evidence GROUP BY "user"
  )
  SELECT COALESCE(
    jsonb_agg(to_jsonb(accepted) ORDER BY accepted."user"),
    '[]'::jsonb
  )
  INTO v_result
  FROM accepted;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public.get_occasion_sign_in_email_statuses(bigint)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_occasion_sign_in_email_statuses(bigint)
  TO authenticated;


CREATE OR REPLACE FUNCTION public.get_occasion_users_for_edit(
  p_occasion_id bigint
)
RETURNS json
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_result jsonb;
  v_users jsonb;
BEGIN
  v_result := public.get_occasion_users_for_edit_invitation_base_v1(
    p_occasion_id
  )::jsonb;
  IF COALESCE((v_result->>'code')::integer, 500) <> 200 THEN
    RETURN v_result::json;
  END IF;

  WITH accepted AS (
    SELECT (entry->>'user')::uuid AS "user" FROM jsonb_array_elements(public.get_occasion_sign_in_email_statuses(p_occasion_id)) entry
  )
  SELECT COALESCE(jsonb_agg(
    row.value || jsonb_build_object(
      'data',
      (CASE WHEN jsonb_typeof(row.value->'data') = 'object'
        THEN row.value->'data' ELSE '{}'::jsonb END - 'is_invited'::text)
      || jsonb_build_object('is_invited', accepted."user" IS NOT NULL)
    )
  ), '[]'::jsonb)
  INTO v_users
  FROM jsonb_array_elements(v_result #> '{data,occasion_users}') row
  LEFT JOIN accepted ON accepted."user" = (row.value->>'user')::uuid;

  RETURN jsonb_set(v_result, '{data,occasion_users}', v_users)::json;
END;
$$;

REVOKE ALL ON FUNCTION public.get_occasion_users_for_edit(bigint)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_occasion_users_for_edit(bigint)
  TO authenticated;


-- Source: database/functions/emails/email_domain.sql
-- Invoker-only helper. Its ACL prevents public use; public domain commands own permissions.
CREATE OR REPLACE FUNCTION public.enqueue_order_email(p_code text,p_data jsonb,p_org bigint,p_occ bigint,p_unit bigint,p_time timestamptz DEFAULT now(),p_request text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE v_order eshop.orders; v_pi eshop.payment_info; v_kind text; v_version bigint; v_key text; v_recipient text; v_existing public.email_messages; v_base_key text;
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 SELECT * INTO v_order FROM eshop.orders WHERE id=coalesce((p_data->>'order_id')::bigint,(p_data#>>'{ticket_order,order,id}')::bigint) FOR UPDATE;
 SELECT * INTO v_pi FROM eshop.payment_info WHERE id=v_order.payment_info;
 IF v_order.id IS NULL OR v_order.occasion<>p_occ THEN RAISE EXCEPTION 'invalid_order_email'; END IF;
 IF v_order.state='stock' THEN RAISE EXCEPTION 'ORDER_ACTION_NOT_ALLOWED'; END IF;
 IF v_order.data ? 'ticketBatchOrigin' AND nullif(trim(v_order.data->>'email'),'') IS NULL THEN
  RETURN jsonb_build_object('state','skipped','reason','no_recipient'); END IF;
 IF v_order.state='storno' AND p_code<>'TICKET_ORDER_STORNO' THEN
  RAISE EXCEPTION 'ORDER_CANCELLED: Cancelled orders are read-only' USING ERRCODE='55000';
 END IF;
 v_kind:=CASE p_code WHEN 'TICKET_ORDER_CONFIRMATION' THEN 'order_confirmation' WHEN 'TICKET_ORDER_PAYMENT_DONE' THEN 'order_payment_notice'
  WHEN 'TICKET_ORDER_REMINDER' THEN 'order_reminder' WHEN 'TICKET_ORDER_STORNO' THEN 'order_storno' WHEN 'TICKET_ORDER_UPDATE' THEN 'order_update'
  WHEN 'ORDER_TICKETS' THEN 'order_tickets' END;
 IF v_kind IS NULL THEN RAISE EXCEPTION 'unsupported_order_email'; END IF;
 v_version:=CASE WHEN v_kind='order_reminder' THEN v_pi.email_reminder_version ELSE v_order.email_payment_version END;
 v_recipient:=coalesce(p_data->>'recipient',v_order.data->>'email');
 v_key:=coalesce(p_request,p_data->>'command_id',v_order.id||':'||v_version||':'||coalesce(v_recipient,'')||':'||coalesce(p_data->>'is_deposit_reminder','false'));
 IF v_kind='order_storno' AND coalesce(p_request,'') NOT LIKE 'manual:%' THEN
  -- requested_by is audit metadata, never proof of an explicit resend.
  v_recipient:=v_order.data->>'email';
  p_data:=jsonb_build_object('order_id',v_order.id);
  v_key:=v_order.id||':'||v_version||':'||coalesce(v_recipient,'')||':storno';
  -- Older Edge follow-ups carried requested_by but no explicit resend ID and
  -- used the generic :false key. Reuse that committed identity rather than
  -- manufacture a second automatic message, including cancelled/expired rows.
  SELECT * INTO v_existing FROM public.email_messages
    WHERE organization=p_org AND order_id=v_order.id AND message_kind='order_storno'
      AND recipient=v_recipient AND source_version=v_version
      AND dedupe_key IN (v_key,v_order.id||':'||v_version||':'||coalesce(v_recipient,'')||':false')
    ORDER BY (dedupe_key=v_key) DESC,id LIMIT 1;
  IF v_existing.id IS NOT NULL THEN v_key:=v_existing.dedupe_key; END IF;
 END IF;
 IF v_kind IN ('order_tickets','order_confirmation') THEN
  SELECT * INTO v_existing FROM public.email_messages WHERE order_id=v_order.id AND message_kind=v_kind AND recipient=v_recipient AND source_version=v_version
    AND workflow_state IN ('pending','preparing','sending','retry_wait','unknown') ORDER BY id DESC LIMIT 1;
  IF v_existing.id IS NOT NULL THEN
   IF p_data->>'requested_by' IS NOT NULL THEN UPDATE public.email_messages SET post_action=post_action||jsonb_build_object('last_manual_request',jsonb_build_object('actor',p_data->>'requested_by','request',p_request,'at',now())) WHERE id=v_existing.id; END IF;
   RETURN jsonb_build_object('message_id',v_existing.message_id,'state',v_existing.workflow_state,'replayed',true);END IF;
  v_base_key:=v_order.id||':'||v_version||':'||coalesce(v_recipient,'')||':false';
  IF p_request IS NULL OR NOT EXISTS(SELECT 1 FROM public.email_messages WHERE order_id=v_order.id AND message_kind=v_kind AND recipient=v_recipient AND source_version=v_version) THEN v_key:=v_base_key;END IF;
 END IF;
 RETURN public.enqueue_email(v_kind,jsonb_build_object('organization',p_org,'occasion',p_occ,'unit',p_unit),v_recipient,p_data,v_key,
 CASE WHEN p_code='ORDER_TICKETS' THEN 'TICKET_ORDER_PAYMENT_DONE' ELSE p_code END,p_time,
 CASE WHEN v_kind='order_reminder' THEN p_time+interval '7 days' ELSE NULL END,v_order.id,v_version);
END $$;

CREATE OR REPLACE FUNCTION public.enqueue_paid_order_tickets(p_order bigint) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
DECLARE v_order eshop.orders; v_occ public.occasions;
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 SELECT * INTO v_order FROM eshop.orders WHERE id=p_order FOR UPDATE;
 SELECT * INTO v_occ FROM public.occasions WHERE id=v_order.occasion;
 IF v_order.data ? 'ticketBatchOrigin' AND coalesce((v_order.data#>>'{ticketBatchOrigin,sendTickets}')::boolean,false) IS NOT TRUE THEN RETURN; END IF;
 IF v_order.state='paid' AND (v_occ.is_order_synchronization_enabled OR v_order.data ? 'ticketBatchOrigin') AND v_order.data ? 'email'
 AND (coalesce(v_order.price,0)<>0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_occ.features) f WHERE f->>'code'='ticket' AND (f->>'is_enabled')::boolean)) THEN
  PERFORM public.enqueue_order_email('ORDER_TICKETS',jsonb_build_object('order_id',p_order),v_occ.organization,v_occ.id,v_occ.unit);
 END IF;
END $$;

CREATE OR REPLACE FUNCTION public.cancel_order_email_intents(p_order bigint) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,extensions AS $$
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 UPDATE public.email_messages SET workflow_state='cancelled',last_error='payment_changed',lease_token=NULL,lease_until=NULL
 WHERE order_id=p_order AND message_kind IN ('order_payment_notice','order_tickets','order_reminder') AND workflow_state IN ('pending','retry_wait','blocked','preparing');
END $$;

CREATE OR REPLACE FUNCTION public.apply_email_post_actions(p_message uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE m record; v_result jsonb;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 FOR m IN SELECT * FROM public.email_messages WHERE workflow_state='accepted' AND post_action_state='pending'
 AND (p_message IS NULL OR message_id=p_message) ORDER BY id LIMIT 20 LOOP
  -- Domain producers lock order before message; follow that order before owning the projection.
  IF m.order_id IS NOT NULL THEN PERFORM 1 FROM eshop.orders WHERE id=m.order_id FOR UPDATE; END IF;
  SELECT * INTO m FROM public.email_messages WHERE id=m.id AND workflow_state='accepted' AND post_action_state='pending' FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE; END IF;
  BEGIN
   IF m.message_kind='order_tickets' THEN
    -- Never resurrect a used/storno ticket or a reverted/cancelled order.
    UPDATE eshop.orders SET state='sent',updated_at=now() WHERE id=m.order_id AND state='paid' AND email_payment_version=m.source_version;
    IF FOUND THEN
     UPDATE eshop.tickets t SET state='sent',updated_at=now()
     FROM eshop.order_product_ticket opt WHERE opt.ticket=t.id AND opt."order"=m.order_id AND t.state='paid'
      AND t.id IN (SELECT jsonb_array_elements_text(m.post_action->'ticket_ids')::bigint);
     INSERT INTO eshop.orders_history("order",data,state,price,currency_code) SELECT id,data,state,price,currency_code FROM eshop.orders WHERE id=m.order_id;
    END IF;
   END IF;
   IF m.message_kind='app_links' AND m.recipient_user IS NOT NULL THEN PERFORM public.mark_app_links_sent(m.occasion,m.recipient_user); END IF;
   IF m.message_kind='deletion_confirm' AND m.post_action ? 'deletion_request' THEN PERFORM public.set_account_deletion_email_state((m.post_action->>'deletion_request')::uuid,true); END IF;
   IF m.post_action ? 'history_id' THEN PERFORM public.add_sent_to_customer_flag((m.post_action->>'history_id')::bigint); END IF;
   IF m.message_kind='order_reminder' THEN
    UPDATE eshop.payment_info SET data=coalesce(data,'{}')||'{"current_version_reminded":true}'::jsonb
    WHERE id=(m.post_action->>'payment_info_id')::bigint AND email_reminder_version=m.source_version;
   END IF;
   UPDATE public.email_messages SET post_action_state='done',last_error=CASE WHEN last_error='post_action_failed' THEN NULL ELSE last_error END WHERE id=m.id;
  EXCEPTION WHEN OTHERS THEN UPDATE public.email_messages SET last_error='post_action_failed' WHERE id=m.id; END;
 END LOOP;
END $$;

-- Account-domain writes and their durable intent are one DB transaction.
CREATE OR REPLACE FUNCTION public.enqueue_account_email(p_operation text,p_domain jsonb,p_context jsonb,p_recipient text,p_sealed jsonb,p_content_hash text,p_dedupe text,p_code text,p_expires timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_context jsonb:=p_context; v_kind text; v_result jsonb; v_domain_result jsonb; v_user uuid:=(p_domain->>'user_id')::uuid; v_source jsonb:='{}'; v_message uuid;
BEGIN
 PERFORM public.require_service_role();
 PERFORM pg_advisory_xact_lock(hashtextextended('email-account:'||(p_context->>'organization')||':'||coalesce(v_user::text,p_dedupe)||':'||p_operation,0));
 -- Command replay is checked before generating/replacing the domain proof.
 SELECT message_id INTO v_message FROM public.email_messages WHERE organization=(p_context->>'organization')::bigint AND dedupe_key=p_dedupe;
 IF v_message IS NOT NULL THEN RETURN jsonb_build_object('message_id',v_message,'replayed',true,'domain',
  CASE WHEN p_operation='register' THEN (SELECT jsonb_build_object('code',200,'id',recipient_user) FROM public.email_messages WHERE message_id=v_message) ELSE NULL END); END IF;
 -- Older clients have no stable request ID. Join any unresolved proof instead of rotating it on a timeout retry.
 IF p_operation IN ('reset_token','deletion_confirm') AND v_user IS NOT NULL THEN
  SELECT message_id INTO v_message FROM public.email_messages WHERE organization=(p_context->>'organization')::bigint AND recipient_user=v_user
   AND message_kind=CASE WHEN p_operation='reset_token' THEN 'reset_password' ELSE 'deletion_confirm' END
   AND (workflow_state IN ('pending','preparing','sending','retry_wait','unknown') OR (p_operation='reset_token' AND workflow_state='accepted')) AND expires_at>now() ORDER BY id DESC LIMIT 1;
  IF v_message IS NOT NULL THEN RETURN jsonb_build_object('message_id',v_message,'replayed',true);END IF;
 END IF;
 IF p_operation='reset_token' THEN
  v_kind:='reset_password';
  IF NOT EXISTS(SELECT 1 FROM public.user_info WHERE id=v_user AND organization=(p_context->>'organization')::bigint) THEN RAISE EXCEPTION 'email_account_scope_mismatch'; END IF;
  INSERT INTO public.user_reset_token("user",token,created_at) VALUES(v_user,(p_domain->>'token')::uuid,now()) ON CONFLICT("user") DO UPDATE SET token=excluded.token,created_at=excluded.created_at;
  v_source:=jsonb_build_object('reset_hash',encode(extensions.digest(p_domain->>'token','sha256'),'hex'));
 ELSIF p_operation='register' THEN
  v_kind:='registration';
  v_domain_result:=public.create_user_from_registration((p_context->>'organization')::bigint,p_recipient,coalesce(p_domain->>'password',p_domain->>'invitation_code'),p_domain->'data',p_domain->>'unit_title');
  IF v_domain_result->>'code'<>'200' THEN RETURN jsonb_build_object('domain',v_domain_result); END IF;
  v_user:=(v_domain_result->>'id')::uuid;
  -- The delivery deadline expires the message, never the reusable password.
  v_source:=jsonb_build_object('password_version',(SELECT encode(extensions.digest(encrypted_password,'sha256'),'hex') FROM auth.users WHERE id=v_user));
 ELSIF p_operation='deletion_confirm' THEN
  v_kind:='deletion_confirm';
  v_domain_result:=public.create_account_deletion_request(v_user,(p_context->>'organization')::bigint,p_domain->>'token_hash',p_expires,p_domain->>'masked_email');
  v_source:=jsonb_build_object('deletion_request',v_domain_result->>'requestId');
 ELSIF p_operation='google_mailbox' THEN
  v_kind:='google_mailbox';
  v_domain_result:=public.google_auth_transition_v1('mailbox_send',(p_domain->>'attempt_id')::uuid,p_domain->>'secret_hash',p_domain->'payload');
  IF (v_domain_result->>'organization')::bigint IS DISTINCT FROM (p_context->>'organization')::bigint OR v_domain_result->>'email' IS DISTINCT FROM p_recipient THEN RAISE EXCEPTION 'email_account_scope_mismatch'; END IF;
  v_source:=jsonb_build_object('google_attempt',p_domain->>'attempt_id','mailbox_hash',p_domain#>>'{payload,mailboxHash}');
 ELSE RAISE EXCEPTION 'invalid_account_email_operation'; END IF;
 IF v_user IS NOT NULL THEN v_context:=v_context||jsonb_build_object('recipient_user',v_user); END IF;
 v_result:=public.enqueue_email(v_kind,v_context,p_recipient,v_source||jsonb_build_object('content_hash',p_content_hash),p_dedupe,p_code,now(),p_expires);
 UPDATE public.email_messages SET prepared=p_sealed,prepared_hash=encode(extensions.digest(p_sealed::text,'sha256'),'hex'),prepared_at=now(),post_action=v_source WHERE message_id=(v_result->>'message_id')::uuid;
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=(v_result->>'message_id')::uuid),true);
 RETURN v_result||jsonb_build_object('domain',v_domain_result);
END $$;
REVOKE ALL ON FUNCTION public.enqueue_account_email(text,jsonb,jsonb,text,jsonb,text,text,text,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.enqueue_account_email(text,jsonb,jsonb,text,jsonb,text,text,text,timestamptz) TO service_role;

CREATE OR REPLACE FUNCTION public.reset_password_and_enqueue_email(p_user uuid,p_password text,p_occasion bigint,p_sealed jsonb,p_content_hash text,p_dedupe text,p_expires timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_answer jsonb; v_context jsonb; v_email text; v_result jsonb; v_existing public.email_messages; v_password_version text;
BEGIN
 -- Reuse the existing hierarchical permission check, including elevated-account protections.
 IF auth.uid() IS NULL OR NOT coalesce(public.get_can_reset_user_password(p_user),false) THEN RAISE EXCEPTION 'password_reset_denied'; END IF;
 PERFORM public.lock_member_access_internal_v1((SELECT unit FROM public.occasions WHERE id=p_occasion));
 PERFORM pg_advisory_xact_lock(hashtextextended('sign-in:'||p_user::text||':'||p_occasion::text,0));
 -- Team invitations never own a password transition, including older clients.
 PERFORM 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_user FOR SHARE;
 IF EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_user
   AND (is_editor OR is_editor_view OR is_manager)) THEN
  RAISE insufficient_privilege USING MESSAGE='Team invitations cannot reset account passwords'; END IF;
 SELECT * INTO v_existing FROM public.email_messages WHERE recipient_user=p_user AND occasion=p_occasion AND message_kind='sign_in' AND (dedupe_key=p_dedupe OR (workflow_state IN ('pending','preparing','sending','retry_wait','unknown','accepted') AND expires_at>now())) ORDER BY id DESC LIMIT 1;
 IF v_existing.id IS NOT NULL THEN
  RETURN jsonb_build_object('message_id',v_existing.message_id,'replayed',true);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_user) THEN RAISE EXCEPTION 'user_not_in_occasion'; END IF;
 v_answer:=public.reset_user_password(p_user,p_password);
 IF v_answer->>'code'<>'200' THEN RAISE EXCEPTION 'password_reset_denied'; END IF;
 SELECT jsonb_build_object('organization',organization,'occasion',id,'unit',unit,'recipient_user',p_user) INTO v_context FROM public.occasions WHERE id=p_occasion;
 v_email:=public.get_user_delivery_email(p_user);
 SELECT encode(extensions.digest(encrypted_password,'sha256'),'hex') INTO v_password_version FROM auth.users WHERE id=p_user;
 v_result:=public.enqueue_email('sign_in',v_context,v_email,jsonb_build_object('password_version',v_password_version,'content_hash',p_content_hash),p_dedupe,'SIGN_IN_CODE',now(),p_expires);
 UPDATE public.email_messages SET prepared=p_sealed,prepared_hash=encode(extensions.digest(p_sealed::text,'sha256'),'hex'),prepared_at=now() WHERE message_id=(v_result->>'message_id')::uuid;
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=(v_result->>'message_id')::uuid),true);
 RETURN v_result;
END $$;
REVOKE ALL ON FUNCTION public.reset_password_and_enqueue_email(uuid,text,bigint,jsonb,text,text,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.reset_password_and_enqueue_email(uuid,text,bigint,jsonb,text,text,timestamptz) TO authenticated;

-- Compatibility name for older clients; both names own the same permanent password transition.
CREATE OR REPLACE FUNCTION public.enqueue_sign_in_code_v1(p_user uuid,p_password text,p_occasion bigint,p_sealed jsonb,p_content_hash text,p_dedupe text,p_expires timestamptz)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.reset_password_and_enqueue_email(p_user,p_password,p_occasion,p_sealed,p_content_hash,p_dedupe,p_expires);
$$;
REVOKE ALL ON FUNCTION public.enqueue_sign_in_code_v1(uuid,text,bigint,jsonb,text,text,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.enqueue_sign_in_code_v1(uuid,text,bigint,jsonb,text,text,timestamptz) TO authenticated;


-- Source: database/functions/emails/email_queue.sql
CREATE OR REPLACE FUNCTION public.wake_email_worker() RETURNS void LANGUAGE plpgsql SECURITY INVOKER
SET search_path=public,extensions AS $$
DECLARE v_url text;
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 IF current_setting('festapp.email_wake',true)='scheduled' THEN RETURN; END IF;
 SELECT worker_url INTO v_url FROM public.email_capacity WHERE NOT paused;
 IF v_url IS NULL OR NOT (EXISTS(SELECT 1 FROM public.email_messages WHERE workflow_state IN ('pending','retry_wait') AND target_time<=now())
  OR EXISTS(SELECT 1 FROM public.email_capacity WHERE quota_at IS NULL OR quota_at<now()-interval '5 minutes')) THEN RETURN; END IF;
 PERFORM set_config('festapp.email_wake','scheduled',true);
 BEGIN
  PERFORM net.http_post(url:=v_url,body:=jsonb_build_object('requestSecret',public.generate_request_secret(120)),timeout_milliseconds:=5000);
 EXCEPTION WHEN OTHERS THEN
  -- Do not invert producer order/message locks against gateway capacity/order locks.
  UPDATE public.email_capacity SET wake_error='wake_failed' WHERE ctid IN (SELECT ctid FROM public.email_capacity FOR UPDATE SKIP LOCKED);
 END;
END $$;

-- Internal service boundary. Domain functions are the only caller for public commands.
CREATE OR REPLACE FUNCTION public.enqueue_email(p_kind text,p_context jsonb,p_recipient text,p_data jsonb,p_dedupe text,
 p_code text DEFAULT '',p_not_before timestamptz DEFAULT now(),p_expires timestamptz DEFAULT NULL,
 p_order bigint DEFAULT NULL,p_version bigint DEFAULT NULL,p_post_action jsonb DEFAULT '{}')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_hash text; v_row public.email_messages; v_org bigint:=(p_context->>'organization')::bigint; v_occ bigint:=(p_context->>'occasion')::bigint; v_unit bigint:=(p_context->>'unit')::bigint;
BEGIN
 p_recipient:=public.normalize_order_email_contact(p_recipient);
 PERFORM public.check_occasion_writable(v_occ);
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 IF v_org IS NULL OR p_kind NOT IN ('order_confirmation','order_payment_notice','order_tickets','order_reminder','order_update','order_storno','custom','registration','sign_in','reset_password','app_links','deletion_confirm','deletion_complete','google_mailbox','gotrue','waitlist_confirmation','waitlist_offer','sale_opening_opened')
 OR p_dedupe IS NULL OR length(p_dedupe)>512 OR (p_recipient IS NOT NULL AND (length(p_recipient)>320 OR position('@' in p_recipient)=0)) THEN RAISE EXCEPTION 'invalid_email_intent'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=v_org) OR
 (v_occ IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=v_occ AND organization=v_org AND (NOT p_context ? 'unit' OR unit IS NOT DISTINCT FROM v_unit))) THEN RAISE EXCEPTION 'email_scope_mismatch'; END IF;
 IF p_order IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=p_order AND occasion=v_occ) THEN RAISE EXCEPTION 'email_order_scope_mismatch'; END IF;
 IF v_occ IS NOT NULL THEN SELECT unit INTO v_unit FROM public.occasions WHERE id=v_occ; END IF;
 -- Snapshot the tenant default only for new unlocalized domain intents. Existing
 -- messages, explicit locales and prepared/encrypted Auth content are untouched.
 IF NOT coalesce(p_data,'{}'::jsonb) ? 'lang' AND
    (p_kind LIKE 'order_%' OR p_kind IN ('waitlist_confirmation','waitlist_offer','sale_opening_opened')) AND
    (SELECT data->>'DEFAULT_LANGUAGE' FROM public.organizations WHERE id=v_org)='en' THEN
   p_data:=coalesce(p_data,'{}'::jsonb)||'{"lang":"en"}'::jsonb;
 END IF;
 v_hash:=encode(extensions.digest(jsonb_build_object('context',p_context-'tracking_policy','recipient',p_recipient,'data',p_data-'requested_by','code',p_code,'version',p_version,'post',p_post_action)::text,'sha256'),'hex');
 INSERT INTO public.email_messages(target_time,code,data,organization,occasion,unit,message_kind,dedupe_key,input_hash,recipient,recipient_user,order_id,source_version,expires_at,producer_actor,priority,workflow_state,post_action,tracking_policy)
 VALUES(p_not_before,p_code,p_data,v_org,v_occ,v_unit,p_kind,p_dedupe,v_hash,p_recipient,(p_context->>'recipient_user')::uuid,p_order,p_version,p_expires,coalesce((p_context->>'actor_id')::uuid,auth.uid()),
 CASE WHEN p_kind IN ('registration','sign_in','reset_password','google_mailbox','gotrue') THEN 0 WHEN p_kind='order_confirmation' THEN 10 ELSE 50 END,
 CASE WHEN p_not_before='infinity' THEN 'blocked' ELSE 'pending' END,p_post_action,CASE WHEN p_kind LIKE 'order_%' OR p_kind IN ('app_links','custom') THEN CASE WHEN p_context->>'tracking_policy'='engagement' THEN 'engagement' ELSE 'open' END ELSE 'disabled' END)
 ON CONFLICT(organization,message_kind,dedupe_key) DO NOTHING RETURNING * INTO v_row;
 IF v_row.id IS NULL THEN
  SELECT * INTO v_row FROM public.email_messages WHERE organization=v_org AND message_kind=p_kind AND dedupe_key=p_dedupe;
  IF v_row.input_hash<>v_hash THEN RAISE EXCEPTION 'email_dedupe_conflict'; END IF;
  RETURN jsonb_build_object('message_id',v_row.message_id,'state',v_row.workflow_state,'replayed',true);
 END IF;
 PERFORM public.admit_email_intent_v1(v_row.id);
 PERFORM public.notification_center_email_internal(v_row.message_id);
 IF p_not_before<=now() THEN PERFORM public.wake_email_worker(); END IF;
 RETURN jsonb_build_object('message_id',v_row.message_id,'state',v_row.workflow_state,'replayed',false);
END $$;

CREATE OR REPLACE FUNCTION public.email_intent_valid(p_message public.email_messages) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_order eshop.orders; v_pi eshop.payment_info; v_occ public.occasions; v_form public.forms; v_feature jsonb; v_deposit jsonb;
BEGIN
 PERFORM public.require_service_role();
 IF public.is_demo_occasion(p_message.occasion) THEN RETURN false; END IF;
 IF p_message.expires_at<=now() THEN RETURN false; END IF;
 IF p_message.message_kind='sign_in' AND EXISTS(SELECT 1 FROM public.occasion_users ou
   WHERE ou.occasion=p_message.occasion AND ou."user"=p_message.recipient_user AND (ou.is_editor OR ou.is_editor_view OR ou.is_manager)) THEN
  RETURN false; END IF;
 IF p_message.message_kind='custom' AND p_message.code='TEAM_INVITATION' THEN
  RETURN EXISTS(SELECT 1 FROM public.access_invitations i WHERE i.message_id=p_message.message_id
   AND i.accepted_at IS NULL AND public.access_invitation_valid_internal_v1(i)
   AND i.email=p_message.recipient AND i.occasion IS NOT DISTINCT FROM p_message.occasion AND i.unit=p_message.unit AND i.organization=p_message.organization);
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='TEAM_ACCESS_NOTICE' THEN
  RETURN public.can_manage_member_access_as_actor_internal_v1(p_message.producer_actor,
   CASE WHEN p_message.occasion IS NULL THEN 'unit' ELSE 'occasion' END,coalesce(p_message.occasion,p_message.unit))
   AND public.get_user_delivery_email(p_message.recipient_user)=p_message.recipient
   AND CASE WHEN p_message.occasion IS NULL THEN EXISTS(SELECT 1 FROM public.unit_users WHERE unit=p_message.unit AND "user"=p_message.recipient_user)
    ELSE EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_message.occasion AND "user"=p_message.recipient_user) END;
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='UNIT_VERIFICATION_REQUEST' THEN
  RETURN EXISTS(SELECT 1 FROM public.unit_legal_profiles p JOIN public.units u ON u.id=p.unit_id
   JOIN public.organization_users ou ON ou.organization=u.organization AND ou."user"=p_message.recipient_user AND ou.is_admin
   WHERE p.unit_id=p_message.unit AND u.organization=p_message.organization AND p.status='pending'
    AND p.revision=p_message.source_version
    AND public.get_user_delivery_email(ou."user")=p_message.recipient);
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='MEASUREMENT_APPROVAL_REQUEST' THEN
  RETURN EXISTS(SELECT 1 FROM analytics.unit_measurement_request q JOIN public.units u ON u.id=q.unit
   JOIN public.organization_users ou ON ou.organization=u.organization AND ou."user"=p_message.recipient_user AND ou.is_admin
   WHERE q.unit=p_message.unit AND u.organization=p_message.organization AND NOT public.is_demo_unit(u.id)
    AND public.unit_measurement_approval_internal(u.id)->'approved'='false'::jsonb
    AND public.get_user_delivery_email(ou."user")=p_message.recipient);
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='BANK_SYNC_WARNING' THEN
  IF NOT EXISTS (SELECT 1 FROM eshop.bank_sync_health h JOIN eshop.bank_sync_connections c ON c.id=h.connection_id
    WHERE h.connection_id=(p_message.data->>'connection_id')::bigint
      AND h.incident_id::text=p_message.data->>'incident_id'
      AND public.bank_sync_alert_ready(c.id)
      AND EXISTS(SELECT 1 FROM eshop.bank_account_users bau WHERE bau."user"=p_message.recipient_user AND bau.is_admin
        AND (bau.bank_account=c.bank_account_id OR bau.bank_account IN
          (SELECT x.bank_account_id FROM eshop.bank_sync_account_aliases x WHERE x.connection_id=c.id)))) THEN RETURN false; END IF;
 END IF;
 IF p_message.message_kind='custom' AND p_message.code='ORDER_OVERVIEW' THEN RETURN false; END IF;
 IF p_message.message_kind='sale_opening_confirmation' THEN RETURN false; END IF;
 IF p_message.message_kind='sale_opening_opened' THEN
  RETURN public.sale_opening_intent_valid_internal(p_message);
 END IF;
 IF p_message.order_id IS NULL THEN
  IF p_message.recipient_user IS NOT NULL AND p_message.message_kind<>'deletion_complete' THEN
   IF p_message.message_kind<>'gotrue' AND public.get_user_delivery_email(p_message.recipient_user) IS DISTINCT FROM p_message.recipient THEN RETURN false; END IF;
   IF p_message.data ? 'sign_in_code_version' AND NOT EXISTS(SELECT 1 FROM public.sign_in_codes WHERE user_id=p_message.recipient_user AND version::text=p_message.data->>'sign_in_code_version' AND expires_at>now() AND consumed_at IS NULL AND attempts<5) THEN RETURN false; END IF;
   IF p_message.data ? 'password_version' AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_message.recipient_user AND encode(extensions.digest(encrypted_password,'sha256'),'hex')=p_message.data->>'password_version') THEN RETURN false; END IF;
   IF p_message.data ? 'reset_hash' AND NOT EXISTS(SELECT 1 FROM public.user_reset_token WHERE "user"=p_message.recipient_user AND encode(extensions.digest(token::text,'sha256'),'hex')=p_message.data->>'reset_hash') THEN RETURN false; END IF;
  END IF;
  IF p_message.data ? 'deletion_request' AND NOT EXISTS(SELECT 1 FROM public.account_deletion_requests WHERE id=(p_message.data->>'deletion_request')::uuid AND status IN ('email_pending','email_sent') AND expires_at>now()) THEN RETURN false; END IF;
  IF p_message.data ? 'google_attempt' AND NOT EXISTS(SELECT 1 FROM public.external_login_attempts WHERE id=(p_message.data->>'google_attempt')::uuid AND mailbox_hash=p_message.data->>'mailbox_hash' AND expires_at>now() AND NOT mailbox_verified) THEN RETURN false; END IF;
  RETURN true;
 END IF;
 SELECT * INTO v_order FROM eshop.orders WHERE id=p_message.order_id;
 IF v_order.id IS NULL OR v_order.occasion<>p_message.occasion THEN RETURN false; END IF;
 IF p_message.data->>'repair_payment_fingerprint' IS NOT NULL AND p_message.data->>'repair_payment_fingerprint' IS DISTINCT FROM public.order_email_payment_fingerprint(v_order.id) THEN RETURN false; END IF;
 IF p_message.message_kind='custom' AND p_message.code='ORDER_OVERVIEW' THEN
  RETURN v_order.data->>'email'=p_message.recipient AND EXISTS(
   SELECT 1 FROM eshop.order_overview_sources s JOIN eshop.waitlist_capabilities c USING(token_hash)
   WHERE s.command_id=(p_message.data->>'order_overview_command')::uuid AND c.kind='order_view'
   AND c.order_id=v_order.id AND c.form_id=v_order.form AND c.organization_id=p_message.organization
   AND c.revoked_at IS NULL AND c.expires_at>now() AND s.expires_at=c.expires_at);
 END IF;
 IF p_message.message_kind='waitlist_confirmation' THEN
  RETURN v_order.state='waitlisted' AND v_order.data->>'email'=p_message.recipient;
 END IF;
 IF p_message.message_kind='waitlist_offer' THEN
  RETURN v_order.state='waitlisted' AND v_order.data->>'email'=p_message.recipient AND EXISTS(
   SELECT 1 FROM eshop.waitlist_offers w JOIN eshop.waitlist_offer_slots s ON s.offer_id=w.id
   WHERE w.id=(p_message.data->>'offer_id')::uuid AND w.order_id=v_order.id AND w.expires_at>clock_timestamp() AND s.outcome='pending');
 END IF;
 IF p_message.message_kind='order_storno' THEN RETURN true; END IF;
 IF v_order.state IN ('storno','expired','preparing_payment') THEN RETURN false; END IF;
 IF p_message.message_kind IN ('order_payment_notice','order_tickets') THEN
  IF EXISTS(SELECT 1 FROM eshop.payment_info WHERE id=v_order.payment_info AND public.payment_method_is_online_internal(payment_method))
   AND public.provider_order_payment_projection_internal(v_order.id)->>'admissionState' IS DISTINCT FROM 'valid' THEN RETURN false; END IF;
  RETURN v_order.state IN ('paid','sent') AND v_order.email_payment_version=p_message.source_version
   AND (p_message.data->>'manual'='true' OR v_order.data->>'email'=p_message.recipient);
 END IF;
 IF p_message.message_kind='order_confirmation' THEN
  RETURN public.order_checkout_email_kind_internal(v_order.id)='order_confirmation'
   AND v_order.state IN ('ordered','paid') AND v_order.email_payment_version=p_message.source_version
   AND v_order.data->>'email'=p_message.recipient;
 END IF;
 IF p_message.message_kind='order_reminder' THEN
  SELECT * INTO v_pi FROM eshop.payment_info WHERE id=v_order.payment_info;
  IF v_pi.payment_method<>'bank' OR v_pi.data#>>'{payment_policy,mode}'='none' THEN RETURN false; END IF;
  SELECT * INTO v_occ FROM public.occasions WHERE id=v_order.occasion;
  SELECT * INTO v_form FROM public.forms WHERE id=v_order.form;
  SELECT x INTO v_feature FROM jsonb_array_elements(v_occ.features) x WHERE x->>'code'='form';
  SELECT x INTO v_deposit FROM jsonb_array_elements(v_occ.features) x WHERE x->>'code'='deposit';
  IF p_message.target_time<now()-interval '7 days' OR p_message.source_version IS DISTINCT FROM v_pi.email_reminder_version
   OR coalesce((v_feature->>'is_enabled')::boolean,false)=false
   OR coalesce((v_form.data->>'is_reminder_enabled')::boolean,(v_feature->>'reminder_is_enabled')::boolean,true)=false THEN RETURN false; END IF;
  IF (p_message.data->>'is_deposit_reminder')::boolean IS TRUE THEN
   RETURN v_order.state IN ('paid','sent') AND v_pi.deposit_amount IS NOT NULL AND coalesce(v_pi.paid,0)-coalesce(v_pi.returned,0)<v_pi.amount
    AND (v_deposit->>'is_enabled')::boolean IS TRUE AND v_deposit->>'deposit_deadline' IS DISTINCT FROM 'on_site';
  END IF;
  RETURN v_order.state='ordered' AND v_pi.deadline IS NOT NULL AND coalesce((v_pi.data->>'current_version_reminded')::boolean,false)=false;
 END IF;
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.recover_email_leases() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 -- Sending expiry is ambiguous, preparation expiry is safe to recover.
 UPDATE public.email_attempts a SET state='unknown',finished_at=now(),error_code='lease_expired'
 FROM public.email_messages m WHERE m.message_id=a.message_id AND m.workflow_state='sending' AND m.lease_until<now() AND a.state='sending';
 UPDATE public.email_messages SET workflow_state='unknown',last_error='lease_expired' WHERE workflow_state='sending' AND lease_until<now();
 UPDATE public.email_attempts a SET state='cancelled',finished_at=now() FROM public.email_messages m
 WHERE a.message_id=m.message_id AND a.lease_token=m.lease_token AND a.state='preparing' AND m.lease_until<now();
 UPDATE public.email_messages SET workflow_state='pending',lease_token=NULL,lease_until=NULL WHERE workflow_state='preparing' AND lease_until<now();

END $$;
REVOKE ALL ON FUNCTION public.recover_email_leases() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.recover_email_leases() TO service_role;

CREATE OR REPLACE FUNCTION public.claim_email() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_row public.email_messages; v_cap public.email_capacity; v_attempt uuid; v_token uuid:=extensions.gen_random_uuid(); v_wait integer;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO v_cap FROM public.email_capacity FOR UPDATE;
 PERFORM public.recover_email_leases();
 UPDATE public.email_capacity SET heartbeat_at=now() WHERE singleton;
 IF v_cap.paused OR v_cap.quota_at IS NULL OR v_cap.quota_at<now()-interval '15 minutes' OR v_cap.circuit_until>now()
  OR (SELECT count(*) FROM public.email_messages WHERE workflow_state='preparing' AND lease_until>now())>=v_cap.max_preparing THEN RETURN NULL; END IF;
 SELECT (x->>'base_limit')::integer INTO v_wait FROM jsonb_array_elements(public.abuse_effective_rules_v1('email.dispatch',NULL,NULL)->'rules') x;
 IF v_wait IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 SELECT * INTO v_row FROM public.email_messages m
 WHERE workflow_state IN ('pending','retry_wait') AND target_time<=now()
 AND (m.prepared IS NOT NULL OR m.message_kind IN ('registration','sign_in','reset_password','google_mailbox','gotrue','order_confirmation')
  OR (SELECT count(*) FROM public.email_messages heavy WHERE heavy.workflow_state='preparing' AND heavy.lease_until>now() AND heavy.prepared IS NULL
   AND heavy.message_kind NOT IN ('registration','sign_in','reset_password','google_mailbox','gotrue','order_confirmation'))<greatest(1,v_cap.max_preparing-1))
 AND NOT EXISTS(SELECT 1 FROM public.email_messages prior WHERE prior.order_id=m.order_id AND prior.message_kind='order_confirmation'
  AND m.message_kind<>'order_confirmation' AND prior.workflow_state NOT IN ('accepted','cancelled','expired'))
 ORDER BY CASE WHEN m.created_at<=now()-make_interval(secs=>v_wait) THEN 0 ELSE priority END,
 (SELECT max(served.last_claimed_at) FROM public.email_messages served WHERE served.organization=m.organization AND served.last_claimed_at IS NOT NULL) NULLS FIRST,
 CASE WHEN m.unit IS NULL THEN (SELECT max(served.last_claimed_at) FROM public.email_messages served WHERE served.organization=m.organization AND served.unit IS NULL AND served.last_claimed_at IS NOT NULL)
 ELSE (SELECT max(served.last_claimed_at) FROM public.email_messages served WHERE served.unit=m.unit AND served.last_claimed_at IS NOT NULL) END NULLS FIRST,target_time,id FOR UPDATE SKIP LOCKED LIMIT 1;
 IF v_row.id IS NULL THEN RETURN NULL; END IF;
 IF NOT public.email_intent_valid(v_row) THEN
  UPDATE public.email_messages SET workflow_state=CASE WHEN expires_at<=now() THEN 'expired' ELSE 'cancelled' END,last_error='intent_invalid' WHERE id=v_row.id;
  RETURN jsonb_build_object('skipped',true);
 END IF;
 UPDATE public.email_messages SET workflow_state='preparing',last_claimed_at=now(),lease_token=v_token,lease_until=now()+interval '90 seconds' WHERE id=v_row.id RETURNING * INTO v_row;
 INSERT INTO public.email_attempts(message_id,lease_token,state) VALUES(v_row.message_id,v_token,'preparing') RETURNING attempt_id INTO v_attempt;
 RETURN to_jsonb(v_row)||jsonb_build_object('attempt_id',v_attempt);
END $$;

-- Keep the global preparation permit while rendering still runs; expired workers cannot renew.
CREATE OR REPLACE FUNCTION public.renew_email_preparation(p_message uuid,p_token uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 UPDATE public.email_messages SET lease_until=now()+interval '90 seconds'
 WHERE message_id=p_message AND lease_token=p_token AND workflow_state='preparing' AND lease_until>now();
 IF NOT FOUND THEN RAISE EXCEPTION 'stale_email_preparation'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.renew_email_preparation(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.renew_email_preparation(uuid,uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.prepare_email(p_message uuid,p_token uuid,p_prepared jsonb,p_post_action jsonb DEFAULT '{}') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 IF octet_length(p_prepared::text)>(SELECT (x->>'base_limit')::bigint
  FROM jsonb_array_elements(public.abuse_effective_rules_v1('email.payload',NULL,NULL)->'rules') x LIMIT 1) THEN
  RAISE configuration_limit_exceeded USING MESSAGE='email_payload_too_large'; END IF;
 UPDATE public.email_messages SET prepared=coalesce(prepared,p_prepared),
 prepared_hash=coalesce(prepared_hash,encode(extensions.digest(p_prepared::text,'sha256'),'hex')),prepared_at=coalesce(prepared_at,now()),
 tracking_policy=CASE WHEN prepared IS NULL AND message_kind LIKE 'order_%' AND p_post_action->>'tracking_policy'='engagement' THEN 'engagement' ELSE tracking_policy END,
 post_action=CASE WHEN prepared IS NULL THEN post_action||p_post_action ELSE post_action END
 WHERE message_id=p_message AND lease_token=p_token AND lease_until>now() AND workflow_state='preparing'
 AND (prepared IS NULL OR prepared=p_prepared);
 IF NOT FOUND THEN RAISE EXCEPTION 'stale_email_preparation'; END IF;
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=p_message),true);
END $$;

CREATE OR REPLACE FUNCTION public.begin_email_send(p_attempt uuid,p_token uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_attempt public.email_attempts; v_row public.email_messages; v_cap public.email_capacity; v_rate numeric; v_daily numeric; v_used numeric; v_detail text; v_retry integer;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.forms f JOIN public.sale_opening_campaigns c ON c.form_id=f.id
  JOIN public.email_messages m ON m.data->>'campaign_id'=c.id::text
  JOIN public.email_attempts a ON a.message_id=m.message_id
  WHERE a.attempt_id=p_attempt AND m.message_kind IN ('sale_opening_opened') FOR UPDATE OF f;
 SELECT * INTO v_cap FROM public.email_capacity FOR UPDATE;
 SELECT * INTO v_attempt FROM public.email_attempts WHERE attempt_id=p_attempt;
 SELECT * INTO v_row FROM public.email_messages WHERE message_id=v_attempt.message_id;
 IF v_row.order_id IS NOT NULL THEN PERFORM 1 FROM eshop.orders WHERE id=v_row.order_id FOR UPDATE; END IF;
 SELECT * INTO v_attempt FROM public.email_attempts WHERE attempt_id=p_attempt FOR UPDATE;
 SELECT * INTO v_row FROM public.email_messages WHERE message_id=v_attempt.message_id FOR UPDATE;
 IF v_attempt.lease_token IS DISTINCT FROM p_token OR v_row.lease_token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'stale_email_attempt'; END IF;
 IF v_attempt.state<>'preparing' THEN RETURN jsonb_build_object('disposition','replay','state',v_attempt.state); END IF;
 IF v_row.workflow_state<>'preparing' OR v_row.lease_until<=now() OR v_row.prepared IS NULL THEN RAISE EXCEPTION 'stale_email_attempt'; END IF;
 IF NOT public.email_intent_valid(v_row) OR EXISTS(SELECT 1 FROM public.email_suppressions WHERE recipient=lower(v_row.recipient)) THEN
  UPDATE public.email_messages SET last_error=CASE WHEN v_row.message_kind='sale_opening_opened' THEN 'intent_invalid' ELSE last_error END,workflow_state=CASE WHEN EXISTS(SELECT 1 FROM public.email_suppressions WHERE recipient=lower(v_row.recipient)) THEN 'suppressed' ELSE 'cancelled' END WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now() WHERE attempt_id=p_attempt;
  PERFORM public.notification_center_email_internal(v_row.message_id);
  RETURN jsonb_build_object('disposition','cancelled');
 END IF;
 -- A partial acceptance can change a queued offer after its rendered snapshot
 -- was cached. Re-render within this same queue before granting a send permit.
 IF v_row.message_kind='waitlist_offer' AND
  (v_row.post_action->>'waitlist_pending_count')::bigint IS DISTINCT FROM
  (SELECT count(*) FROM eshop.waitlist_offer_slots
   WHERE offer_id=(v_row.data->>'offer_id')::uuid AND outcome='pending') THEN
  UPDATE public.email_messages SET workflow_state='pending',target_time=now(),
   prepared=NULL,prepared_hash=NULL,prepared_at=NULL,
   post_action=post_action-'waitlist_pending_count',lease_token=NULL,lease_until=NULL,
   last_error='offer_snapshot_changed' WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now(),
   error_code='offer_snapshot_changed' WHERE attempt_id=p_attempt;
  RETURN jsonb_build_object('disposition','deferred');
 END IF;
 -- Only unstarted provider attempts can discard a stale Wallet snapshot.
 IF v_row.message_kind='order_tickets' AND v_row.post_action->>'wallet_fingerprint'
  IS DISTINCT FROM public.ticket_wallet_fingerprint(v_row.occasion) THEN
  UPDATE public.email_messages SET workflow_state='pending',target_time=now(),prepared=NULL,prepared_hash=NULL,prepared_at=NULL,
   post_action=post_action-'wallet_fingerprint',lease_token=NULL,lease_until=NULL,last_error='wallet_snapshot_changed' WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now(),error_code='wallet_snapshot_changed' WHERE attempt_id=p_attempt;
  RETURN jsonb_build_object('disposition','deferred');
 END IF;
 v_rate:=CASE WHEN v_cap.shared_account THEN least(v_cap.max_rate*0.8,v_cap.allocated_rate) ELSE v_cap.max_rate*0.8 END*v_cap.rate_factor;
 v_daily:=CASE WHEN v_cap.shared_account THEN least(v_cap.daily_quota,v_cap.allocated_daily) ELSE v_cap.daily_quota END*0.9;
 -- Count all local starts since snapshot plus provider's rolling usage; conservative during drift.
 SELECT count(*) INTO v_used FROM public.email_attempts WHERE began_at>now()-interval '24 hours' AND (began_at>v_cap.quota_at OR state IN ('sending','unknown')) AND state IN ('sending','accepted','unknown');
 IF v_cap.paused OR v_cap.quota_at IS NULL OR v_cap.quota_at<now()-interval '15 minutes' OR v_rate IS NULL OR v_rate<=0 OR v_daily IS NULL
 OR (v_cap.shared_account AND (v_cap.allocated_rate IS NULL OR v_cap.allocated_daily IS NULL)) OR v_cap.provider_sent_24h+v_used>=v_daily
 OR v_cap.next_send_at>now() OR v_cap.circuit_until>now()
 OR (v_cap.provider_outage_streak>0 AND v_cap.probe_until>now())
 OR (SELECT count(*) FROM public.email_messages WHERE workflow_state='sending' AND lease_until>now())>=v_cap.max_sending THEN
  UPDATE public.email_messages SET workflow_state='pending',target_time=greatest(now()+interval '1 second',coalesce(v_cap.next_send_at,now()),coalesce(v_cap.circuit_until,now()),coalesce(v_cap.probe_until,now())),lease_token=NULL,lease_until=NULL,last_error='capacity_deferred' WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now(),error_code='capacity_deferred' WHERE attempt_id=p_attempt;
  RETURN jsonb_build_object('disposition','deferred');
 END IF;
 -- Recipient admission at enqueue does not protect against many future intents
 -- converging on one date. Meter the actual fenced send, with separate essential
 -- classes so ordinary bulk cannot consume Auth or accepted-order capacity.
 BEGIN
  PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('email.send.'||v_row.admission_class,v_row.unit,v_row.organization),
   jsonb_build_object('recipient',public.abuse_recipient_key_v1(v_row.recipient)));
 EXCEPTION WHEN SQLSTATE 'PT429' THEN
  GET STACKED DIAGNOSTICS v_detail=PG_EXCEPTION_DETAIL;
  v_retry:=greatest(coalesce((v_detail::jsonb->>'retryAfterSeconds')::integer,60),1);
  UPDATE public.email_messages SET workflow_state='pending',target_time=now()+make_interval(secs=>v_retry),lease_token=NULL,lease_until=NULL,last_error='recipient_deferred' WHERE id=v_row.id;
  UPDATE public.email_attempts SET state='cancelled',finished_at=now(),error_code='recipient_deferred' WHERE attempt_id=p_attempt;
  RETURN jsonb_build_object('disposition','deferred');
 END;
 UPDATE public.email_capacity SET next_send_at=clock_timestamp()+make_interval(secs=>(1/v_rate)::double precision),
 probe_until=CASE WHEN provider_outage_streak>0 THEN now()+interval '90 seconds' ELSE NULL END,
 probe_attempt=CASE WHEN provider_outage_streak>0 THEN p_attempt ELSE NULL END WHERE singleton;
 UPDATE public.email_attempts SET state='sending',began_at=now() WHERE attempt_id=p_attempt;
 UPDATE public.email_messages SET workflow_state='sending',attempt_count=attempt_count+1 WHERE id=v_row.id;
 RETURN jsonb_build_object('disposition','send','message',to_jsonb(v_row));
END $$;

CREATE OR REPLACE FUNCTION public.finish_email_attempt(p_attempt uuid,p_token uuid,p_outcome text,p_provider_id text DEFAULT NULL,p_error text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_a public.email_attempts; v_m public.email_messages; v_delay integer;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 SELECT * INTO v_a FROM public.email_attempts WHERE attempt_id=p_attempt FOR UPDATE;
 SELECT * INTO v_m FROM public.email_messages WHERE message_id=v_a.message_id FOR UPDATE;
 IF v_a.lease_token IS DISTINCT FROM p_token OR v_m.lease_token IS DISTINCT FROM p_token THEN RAISE EXCEPTION 'stale_email_completion'; END IF;
 IF v_a.state='accepted' THEN RETURN; END IF;
 IF p_outcome NOT IN ('accepted','retry','dead','unknown','preparation_failed') THEN RAISE EXCEPTION 'invalid_email_outcome'; END IF;
 IF p_outcome='accepted' AND (p_provider_id IS NULL OR v_a.state NOT IN ('sending','unknown')) THEN RAISE EXCEPTION 'invalid_email_acceptance'; END IF;
 IF p_outcome IN ('retry','dead','unknown') AND v_a.state<>'sending' THEN RAISE EXCEPTION 'invalid_email_failure'; END IF;
 IF p_outcome='preparation_failed' AND v_a.state<>'preparing' THEN RAISE EXCEPTION 'invalid_email_preparation_failure'; END IF;
 IF p_outcome='accepted' THEN
  UPDATE public.email_capacity SET provider_outage_streak=0,probe_until=NULL,probe_attempt=NULL,circuit_until=NULL WHERE probe_attempt=p_attempt;
  UPDATE public.email_attempts SET state='accepted',provider_message_id=p_provider_id,finished_at=now() WHERE attempt_id=p_attempt;
  UPDATE public.email_messages SET workflow_state='accepted',provider_message_id=p_provider_id,accepted_at=coalesce(accepted_at,now()),last_error=NULL WHERE id=v_m.id;
 ELSE
  v_delay:=(ARRAY[15,60,300,1800,7200])[least(greatest(v_m.attempt_count,1),5)];
  UPDATE public.email_attempts SET state=CASE WHEN p_outcome='unknown' THEN 'unknown' ELSE 'not_accepted' END,error_code=p_error,finished_at=now() WHERE attempt_id=p_attempt;
  UPDATE public.email_messages SET workflow_state=CASE WHEN p_outcome='unknown' THEN 'unknown' WHEN p_outcome='dead' OR attempt_count+CASE WHEN p_outcome='preparation_failed' THEN 1 ELSE 0 END>=8 THEN 'dead' ELSE 'retry_wait' END,
   attempt_count=attempt_count+CASE WHEN p_outcome='preparation_failed' THEN 1 ELSE 0 END,
   target_time=now()+make_interval(secs=>v_delay*(0.8+random()*0.4)),last_error=left(p_error,100),lease_until=NULL WHERE id=v_m.id;
  IF p_outcome='unknown' THEN UPDATE public.email_capacity SET provider_outage_streak=least(provider_outage_streak+1,10),
   probe_until=NULL,probe_attempt=NULL,circuit_until=now()+make_interval(secs=>least(300,30*power(2,least(provider_outage_streak,4)))::double precision) WHERE singleton; END IF;
  PERFORM public.notification_center_email_internal(v_m.message_id);
  IF p_error='throttled' THEN UPDATE public.email_capacity SET rate_factor=greatest(rate_factor/2,0.01),probe_until=NULL,probe_attempt=NULL,circuit_until=now()+interval '15 seconds' WHERE singleton; END IF;
 END IF;
 PERFORM public.reconcile_email_events();
 PERFORM public.notification_center_email_internal(v_m.message_id);
END $$;

CREATE OR REPLACE FUNCTION public.reconcile_email_events() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_event record;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 WITH matched AS (UPDATE public.email_delivery_events e SET message_id=m.message_id FROM public.email_messages m
 WHERE e.message_id IS NULL AND lower(e.recipient)=lower(m.recipient)
 AND (m.provider_message_id=e.provider_message_id OR EXISTS(SELECT 1 FROM public.email_attempts a WHERE a.message_id=m.message_id AND a.attempt_id=e.attempt_id AND a.state IN ('sending','unknown','accepted'))) RETURNING e.message_id)
 UPDATE public.email_messages m SET feedback_pending=true WHERE m.message_id IN (SELECT message_id FROM matched);
 FOR v_event IN SELECT message_id,min(provider_time) FILTER(WHERE event_type='delivery') delivery,
 min(provider_time) FILTER(WHERE event_type='bounce') bounce,min(provider_time) FILTER(WHERE event_type='complaint') complaint,
 min(provider_time) FILTER(WHERE event_type='open') opened,min(provider_time) FILTER(WHERE event_type='click') clicked,
 min(provider_time) FILTER(WHERE event_type IN ('send','delivery','open','click','bounce','complaint','delay')) accepted,
 min(provider_message_id) provider_id,max(event_type) FILTER(WHERE event_type IN ('reject','rendering_failure','delay')) failure
 FROM public.email_delivery_events WHERE message_id IN (SELECT message_id FROM public.email_messages WHERE workflow_state IN ('sending','unknown') OR feedback_pending) GROUP BY message_id LOOP
  UPDATE public.email_messages SET delivered_at=least(delivered_at,v_event.delivery),bounced_at=least(bounced_at,v_event.bounce),complained_at=least(complained_at,v_event.complaint),
   opened_at=CASE WHEN tracking_policy<>'disabled' THEN least(opened_at,v_event.opened) ELSE NULL END,
   clicked_at=CASE WHEN tracking_policy='engagement' THEN least(clicked_at,v_event.clicked) ELSE NULL END,provider_failure=v_event.failure,
   accepted_at=coalesce(accepted_at,v_event.accepted),provider_message_id=coalesce(provider_message_id,v_event.provider_id),
   workflow_state=CASE WHEN v_event.accepted IS NOT NULL AND workflow_state IN ('sending','unknown') THEN 'accepted' ELSE workflow_state END,feedback_pending=false
  WHERE message_id=v_event.message_id;
  PERFORM public.notification_center_email_internal(v_event.message_id);
  UPDATE public.email_attempts SET state='accepted',provider_message_id=v_event.provider_id,finished_at=coalesce(finished_at,now())
  WHERE message_id=v_event.message_id AND state IN ('sending','unknown') AND v_event.accepted IS NOT NULL;
 INSERT INTO public.email_suppressions(recipient,reason)
 SELECT lower(recipient),CASE WHEN bool_or(event_type='complaint') THEN 'complaint' ELSE 'hard_bounce' END
 FROM public.email_delivery_events WHERE message_id=v_event.message_id AND (event_type='complaint' OR (event_type='bounce' AND hard_bounce))
 GROUP BY lower(recipient)
 ON CONFLICT(recipient) DO UPDATE SET reason=CASE WHEN email_suppressions.reason='complaint' THEN 'complaint' ELSE excluded.reason END;
 END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.record_email_events(p_events jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 IF jsonb_typeof(p_events)<>'array' OR jsonb_array_length(p_events)>100 THEN RAISE EXCEPTION 'invalid_event_batch'; END IF;
 INSERT INTO public.email_delivery_events(event_key,provider_message_id,attempt_id,recipient,event_type,provider_time,hard_bounce,invalid_recipient)
 SELECT e->>'key',e->>'provider_id',(e->>'attempt_id')::uuid,e->>'recipient',e->>'type',(e->>'time')::timestamptz,coalesce((e->>'hard_bounce')::boolean,false),coalesce((e->>'invalid_recipient')::boolean,false)
 FROM jsonb_array_elements(p_events) e ON CONFLICT(event_key) DO NOTHING;
 PERFORM public.reconcile_email_events();
END $$;
REVOKE ALL ON FUNCTION public.record_email_events(jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_email_events(jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.record_email_event(p_event jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 PERFORM public.record_email_events(jsonb_build_array(p_event));
END $$;

CREATE OR REPLACE FUNCTION public.enqueue_prepared_email(p_kind text,p_context jsonb,p_recipient text,p_sealed jsonb,p_dedupe text,p_content_hash text,p_code text,p_expires timestamptz DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_result jsonb; v_m public.email_messages;
BEGIN
 PERFORM public.require_service_role();
 -- Use stable digest as canonical data; nonce/ciphertext is not part of dedupe equality.
 v_result:=public.enqueue_email(p_kind,p_context,p_recipient,jsonb_build_object('content_hash',p_content_hash),p_dedupe,p_code,now(),p_expires);
 UPDATE public.email_messages SET prepared=coalesce(prepared,p_sealed),prepared_hash=coalesce(prepared_hash,encode(extensions.digest(p_sealed::text,'sha256'),'hex')),prepared_at=coalesce(prepared_at,now())
 WHERE message_id=(v_result->>'message_id')::uuid AND workflow_state IN ('pending','blocked','preparing','retry_wait');
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=(v_result->>'message_id')::uuid),true);
 RETURN v_result;
END $$;

CREATE OR REPLACE FUNCTION public.get_internal_email_state(p_message uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 RETURN (SELECT workflow_state FROM public.email_messages WHERE message_id=p_message);
END $$;

CREATE OR REPLACE FUNCTION public.refresh_email_quota(p_account text,p_region text,p_rate numeric,p_daily numeric,p_used numeric) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE c public.email_capacity;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO c FROM public.email_capacity FOR UPDATE;
 IF c.account_id IS DISTINCT FROM p_account OR c.region IS DISTINCT FROM p_region OR p_rate IS NULL OR p_daily IS NULL OR p_used IS NULL OR p_rate<=0 OR p_daily<=0 OR p_used<0 THEN RAISE EXCEPTION 'email_quota_identity_mismatch'; END IF;
 UPDATE public.email_capacity SET max_rate=p_rate,daily_quota=p_daily,provider_sent_24h=p_used,quota_at=now(),wake_error=NULL,rate_factor=least(1,rate_factor+0.05) WHERE singleton;
END $$;

CREATE OR REPLACE FUNCTION public.invalidate_email_quota(p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN PERFORM public.require_service_role();UPDATE public.email_capacity SET quota_at=NULL,wake_error=left(p_reason,100) WHERE singleton;END $$;
REVOKE ALL ON FUNCTION public.invalidate_email_quota(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.invalidate_email_quota(text) TO service_role;

